window.ETEXTBOOK={"units": [{"id": "u1", "title": "导入问题", "sections": [{"id": "u1_s0", "title": "导入问题", "paras": [{"id": "u1_s0_p1", "buf": ["1 Can you name some popular cultural activities in modern China?"], "text": "1 Can you name some popular cultural activities in modern China?", "chunks": ["1 Can you name some popular cultural activities in modern China?"]}, {"id": "u1_s0_p2", "buf": ["2 How have advancements in technology influenced the way Chinese people spend their leisure time and enjoy entertainment?"], "text": "2 How have advancements in technology influenced the way Chinese people spend their leisure time and enjoy entertainment?", "chunks": ["2 How have advancements in technology influenced the way Chinese people spend their leisure time and enjoy entertainment?"]}, {"id": "u1_s0_p3", "buf": ["3 What are some iconic natural attractions in China that you think best represent the country's landscape?"], "text": "3 What are some iconic natural attractions in China that you think best represent the country's landscape?", "chunks": ["3 What are some iconic natural attractions in China that you think best represent the country's landscape?"]}, {"id": "u1_s0_p4", "buf": ["4 What do you think people can learn from visiting red tourism sites?"], "text": "4 What do you think people can learn from visiting red tourism sites?", "chunks": ["4 What do you think people can learn from visiting red tourism sites?"]}]}]}, {"id": "u2", "title": "休闲娱乐", "sections": [{"id": "u2_s0", "title": "休闲娱乐", "paras": [{"id": "u2_s0_p1", "buf": ["Leisure and entertainment have become an essential part of Chinese people's daily lives. People are increasingly drawn to cultural activities for spiritual enrichment, especially as they enjoy more free time and higher incomes. Visiting museums, art galleries, and cultural centres and going to concerts, the theatre, and the cinema have become popular ways to spend leisure time."], "text": "Leisure and entertainment have become an essential part of Chinese people's daily lives. People are increasingly drawn to cultural activities for spiritual enrichment, especially as they enjoy more free time and higher incomes. Visiting museums, art galleries, and cultural centres and going to concerts, the theatre, and the cinema have become popular ways to spend leisure time.", "chunks": ["Leisure and entertainment have become an essential part of Chinese people's daily lives. People are increasingly drawn to cultural activities for spiritual enrichment, especially as they enjoy more free time and higher incomes. Visiting museums, art galleries, and cultural centres and going to concerts, the theatre, and the cinema have become popular ways to spend leisure time."]}, {"id": "u2_s0_p2", "buf": ["Outdoor activities, such as visiting parks and city walks, have become some of the most popular leisure choices, largely because they are low-cost and relaxing. Additionally, more strenuous activities like running, cycling, and hiking are attracting more participants, fuelled by greater awareness of the importance of health and well-being."], "text": "Outdoor activities, such as visiting parks and city walks, have become some of the most popular leisure choices, largely because they are low-cost and relaxing. Additionally, more strenuous activities like running, cycling, and hiking are attracting more participants, fuelled by greater awareness of the importance of health and well-being.", "chunks": ["Outdoor activities, such as visiting parks and city walks, have become some of the most popular leisure choices, largely because they are low-cost and relaxing. Additionally, more strenuous activities like running, cycling, and hiking are attracting more participants, fuelled by greater awareness of the importance of health and well-being."]}, {"id": "u2_s0_p3", "buf": ["China has been transforming into a digitally connected society. Digital entertainment has become an important part of modern life, offering new and diverse forms of leisure experiences in the virtual world. Various online platforms allow people to connect with friends, share life moments, browse the news, and engage in online discussions."], "text": "China has been transforming into a digitally connected society. Digital entertainment has become an important part of modern life, offering new and diverse forms of leisure experiences in the virtual world. Various online platforms allow people to connect with friends, share life moments, browse the news, and engage in online discussions.", "chunks": ["China has been transforming into a digitally connected society. Digital entertainment has become an important part of modern life, offering new and diverse forms of leisure experiences in the virtual world. Various online platforms allow people to connect with friends, share life moments, browse the news, and engage in online discussions."]}, {"id": "u2_s0_p4", "buf": ["These diverse leisure activities not only enrich people's free time but also foster cultural exchange, support economic growth, and contribute to the development of the cultural industry."], "text": "These diverse leisure activities not only enrich people's free time but also foster cultural exchange, support economic growth, and contribute to the development of the cultural industry.", "chunks": ["These diverse leisure activities not only enrich people's free time but also foster cultural exchange, support economic growth, and contribute to the development of the cultural industry."]}]}, {"id": "u2_s1", "title": "文化休闲活动", "paras": [{"id": "u2_s1_p1", "buf": ["Compared with traditional leisure activities, Chinese people's recreational pursuits are now showing a trend of diversification and enrichment. Increasingly, people are eager to participate in various cultural activities for relaxation and enjoyment."], "text": "Compared with traditional leisure activities, Chinese people's recreational pursuits are now showing a trend of diversification and enrichment. Increasingly, people are eager to participate in various cultural activities for relaxation and enjoyment.", "chunks": ["Compared with traditional leisure activities, Chinese people's recreational pursuits are now showing a trend of diversification and enrichment. Increasingly, people are eager to participate in various cultural activities for relaxation and enjoyment."]}, {"id": "u2_s1_p2", "buf": ["China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally in terms of quantity. In order to attract and engage visitors, many museums have applied innovative technologies in their exhibitions. In 2023, for example, the National Museum of China (中国国家博物馆) in Beijing hosted an exhibition titled \"Magnificence and Grandeur: Immersive Experience of Grotto Art\", in which technologies like artificial intelligence and digital imaging were used to recreate cultural treasures such as the Mogao Grottoes (莫高窟) and the Longmen Grottoes (龙门石窟)."], "text": "China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally in terms of quantity. In order to attract and engage visitors, many museums have applied innovative technologies in their exhibitions. In 2023, for example, the National Museum of China (中国国家博物馆) in Beijing hosted an exhibition titled \"Magnificence and Grandeur: Immersive Experience of Grotto Art\", in which technologies like artificial intelligence and digital imaging were used to recreate cultural treasures such as the Mogao Grottoes (莫高窟) and the Longmen Grottoes (龙门石窟).", "chunks": ["China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally in terms of quantity. In order to attract and engage visitors, many museums have applied innovative technologies in their exhibitions. In 2023, for example, the National Museum of China (中国国家博物馆) in Beijing hosted an exhibition titled \"Magnificence and Grandeur: Immersive Experience of Grotto Art\", in which technologies like artificial intelligence and digital imaging were used to recreate cultural treasures such as the Mogao Grottoes (莫高窟) and the Longmen Grottoes (龙门石窟)."]}, {"id": "u2_s1_p3", "buf": ["China's cultural scene is remarkably rich and diverse, providing abundant opportunities for artistic enjoyment. For example, the National Centre for the Performing Arts (国家大剧院), a renowned performing arts venue, hosts concerts, operas, and theatre performances featuring renowned artists from around the world. This arts centre has staged more than 100 productions and commissioned works since 2007, covering opera, drama, Peking Opera, and dance drama."], "text": "China's cultural scene is remarkably rich and diverse, providing abundant opportunities for artistic enjoyment. For example, the National Centre for the Performing Arts (国家大剧院), a renowned performing arts venue, hosts concerts, operas, and theatre performances featuring renowned artists from around the world. This arts centre has staged more than 100 productions and commissioned works since 2007, covering opera, drama, Peking Opera, and dance drama.", "chunks": ["China's cultural scene is remarkably rich and diverse, providing abundant opportunities for artistic enjoyment. For example, the National Centre for the Performing Arts (国家大剧院), a renowned performing arts venue, hosts concerts, operas, and theatre performances featuring renowned artists from around the world. This arts centre has staged more than 100 productions and commissioned works since 2007, covering opera, drama, Peking Opera, and dance drama."]}, {"id": "u2_s1_p4", "buf": ["New cultural venues such as creative bazaars, handicraft exhibitions, and cultural and creative industry parks also provide opportunities for people to engage with arts. For example, Shanghai's Tianzifang is an international cultural and creative industry zone that is home to nearly 400 stores, including art galleries, studios, handicraft stores, fashion boutiques, restaurants, and cafés. Visitors can enjoy a variety of unique artworks, buy handicrafts, and attend various creative workshops and art lectures. Similarly, Beijing's 798 Art District attracts countless artists and tourists alike, transforming a former industrial site into a vibrant cultural hub."], "text": "New cultural venues such as creative bazaars, handicraft exhibitions, and cultural and creative industry parks also provide opportunities for people to engage with arts. For example, Shanghai's Tianzifang is an international cultural and creative industry zone that is home to nearly 400 stores, including art galleries, studios, handicraft stores, fashion boutiques, restaurants, and cafés. Visitors can enjoy a variety of unique artworks, buy handicrafts, and attend various creative workshops and art lectures. Similarly, Beijing's 798 Art District attracts countless artists and tourists alike, transforming a former industrial site into a vibrant cultural hub.", "chunks": ["New cultural venues such as creative bazaars, handicraft exhibitions, and cultural and creative industry parks also provide opportunities for people to engage with arts. For example, Shanghai's Tianzifang is an international cultural and creative industry zone that is home to nearly 400 stores, including art galleries, studios, handicraft stores, fashion boutiques, restaurants, and cafés. Visitors can enjoy a variety of unique artworks, buy handicrafts, and attend various creative workshops and art lectures. Similarly, Beijing's 798 Art District attracts countless artists and tourists alike, transforming a former industrial site into a vibrant cultural hub."]}, {"id": "u2_s1_p5", "buf": ["Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to thrive. The launch of public-interest cultural programmes (文化惠民工程) and the promotion of cultural revitalisation in rural areas bring more cultural performances and activities to rural communities, enriching residents' lives. In many rural areas, performances are held at cultural squares and in farmhouses, captivating local villagers. The \"village spring festival gala (村晚)\" has become immensely popular in recent years. In 2023, more than 20,000 such galas were held nationwide, with approximately 130 million participants."], "text": "Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to thrive. The launch of public-interest cultural programmes (文化惠民工程) and the promotion of cultural revitalisation in rural areas bring more cultural performances and activities to rural communities, enriching residents' lives. In many rural areas, performances are held at cultural squares and in farmhouses, captivating local villagers. The \"village spring festival gala (村晚)\" has become immensely popular in recent years. In 2023, more than 20,000 such galas were held nationwide, with approximately 130 million participants.", "chunks": ["Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to thrive. The launch of public-interest cultural programmes (文化惠民工程) and the promotion of cultural revitalisation in rural areas bring more cultural performances and activities to rural communities, enriching residents' lives. In many rural areas, performances are held at cultural squares and in farmhouses, captivating local villagers. The \"village spring festival gala (村晚)\" has become immensely popular in recent years. In 2023, more than 20,000 such galas were held nationwide, with approximately 130 million participants."]}]}, {"id": "u2_s2", "title": "体育休闲活动", "paras": [{"id": "u2_s2_p1", "buf": ["Chinese people are becoming increasingly health-conscious. Regular physical activity has become a common part of daily life. Runners can be found everywhere—in city parks, along riversides, and on mountain trails. Beyond running, activities such as rock climbing, skateboarding, and street dancing are gaining popularity among young people. Meanwhile, more relaxing pursuits such as yoga and tai chi chuan attract participants of all ages seeking to reduce stress and improve flexibility and balance."], "text": "Chinese people are becoming increasingly health-conscious. Regular physical activity has become a common part of daily life. Runners can be found everywhere—in city parks, along riversides, and on mountain trails. Beyond running, activities such as rock climbing, skateboarding, and street dancing are gaining popularity among young people. Meanwhile, more relaxing pursuits such as yoga and tai chi chuan attract participants of all ages seeking to reduce stress and improve flexibility and balance.", "chunks": ["Chinese people are becoming increasingly health-conscious. Regular physical activity has become a common part of daily life. Runners can be found everywhere—in city parks, along riversides, and on mountain trails. Beyond running, activities such as rock climbing, skateboarding, and street dancing are gaining popularity among young people. Meanwhile, more relaxing pursuits such as yoga and tai chi chuan attract participants of all ages seeking to reduce stress and improve flexibility and balance."]}, {"id": "u2_s2_p2", "buf": ["The integration of sports into tourism has become a key trend in modern leisure, offering a blend of adventure and relaxation. Hiking in scenic mountain areas, cycling along picturesque routes, and engaging in water sports are just a few examples of how modern travel combines physical activity with exploration. The rise of sports tourism highlights the growing interest in destinations that combine natural beauty with opportunities for physical challenges. These trends showcase a modern approach to leisure that values both adventure and connection with nature."], "text": "The integration of sports into tourism has become a key trend in modern leisure, offering a blend of adventure and relaxation. Hiking in scenic mountain areas, cycling along picturesque routes, and engaging in water sports are just a few examples of how modern travel combines physical activity with exploration. The rise of sports tourism highlights the growing interest in destinations that combine natural beauty with opportunities for physical challenges. These trends showcase a modern approach to leisure that values both adventure and connection with nature.", "chunks": ["The integration of sports into tourism has become a key trend in modern leisure, offering a blend of adventure and relaxation. Hiking in scenic mountain areas, cycling along picturesque routes, and engaging in water sports are just a few examples of how modern travel combines physical activity with exploration. The rise of sports tourism highlights the growing interest in destinations that combine natural beauty with opportunities for physical challenges. These trends showcase a modern approach to leisure that values both adventure and connection with nature."]}, {"id": "u2_s2_p3", "buf": ["The \"village super league (村超)\", a non-professional football league held in Rongjiang County, Guizhou Province, has become a hot topic and gained massive popularity across China. More than just a football competition, it has become a vibrant platform for demonstrating the vitality and cultural charm of rural China. Its appeal lies in its down-to-earth style, festive atmosphere, and rich ethnic elements. Added to these are the players' impressive skills, passionate performances, and the spectators' infectious enthusiasm."], "text": "The \"village super league (村超)\", a non-professional football league held in Rongjiang County, Guizhou Province, has become a hot topic and gained massive popularity across China. More than just a football competition, it has become a vibrant platform for demonstrating the vitality and cultural charm of rural China. Its appeal lies in its down-to-earth style, festive atmosphere, and rich ethnic elements. Added to these are the players' impressive skills, passionate performances, and the spectators' infectious enthusiasm.", "chunks": ["The \"village super league (村超)\", a non-professional football league held in Rongjiang County, Guizhou Province, has become a hot topic and gained massive popularity across China. More than just a football competition, it has become a vibrant platform for demonstrating the vitality and cultural charm of rural China. Its appeal lies in its down-to-earth style, festive atmosphere, and rich ethnic elements. Added to these are the players' impressive skills, passionate performances, and the spectators' infectious enthusiasm."]}]}, {"id": "u2_s3", "title": "数字娱乐", "paras": [{"id": "u2_s3_p1", "buf": ["In recent years, digital technology has revolutionised leisure and cultural experiences in China. From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions and experiencing smart tourism (智慧旅游), digital entertainment has become an integral part of modern life. These innovative forms of online leisure are not only reshaping how people enjoy themselves, but are also meeting their diverse needs in a rapidly evolving digital landscape."], "text": "In recent years, digital technology has revolutionised leisure and cultural experiences in China. From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions and experiencing smart tourism (智慧旅游), digital entertainment has become an integral part of modern life. These innovative forms of online leisure are not only reshaping how people enjoy themselves, but are also meeting their diverse needs in a rapidly evolving digital landscape.", "chunks": ["In recent years, digital technology has revolutionised leisure and cultural experiences in China. From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions and experiencing smart tourism (智慧旅游), digital entertainment has become an integral part of modern life. These innovative forms of online leisure are not only reshaping how people enjoy themselves, but are also meeting their diverse needs in a rapidly evolving digital landscape."]}]}, {"id": "u2_s4", "title": "网上购物", "paras": [{"id": "u2_s4_p1", "buf": ["In China, online shopping has become an important part of daily life. By connecting the physical world with the virtual one, online shopping saves people time and energy. According to the 56th Statistical Report on Internet Development in China released by the China Internet Network Information Center in July 2025, the number of internet users in China reached more than 1.12 billion by June 2025, with an internet penetration rate of 79.7%. Among them, about 0.98 billion were users of online shopping platforms, accounting for 86.9% of all internet users. Meanwhile, the popularity of livestream shopping has turned interactive online shopping into a new form of digital entertainment."], "text": "In China, online shopping has become an important part of daily life. By connecting the physical world with the virtual one, online shopping saves people time and energy. According to the 56th Statistical Report on Internet Development in China released by the China Internet Network Information Center in July 2025, the number of internet users in China reached more than 1.12 billion by June 2025, with an internet penetration rate of 79.7%. Among them, about 0.98 billion were users of online shopping platforms, accounting for 86.9% of all internet users. Meanwhile, the popularity of livestream shopping has turned interactive online shopping into a new form of digital entertainment.", "chunks": ["In China, online shopping has become an important part of daily life. By connecting the physical world with the virtual one, online shopping saves people time and energy. According to the 56th Statistical Report on Internet Development in China released by the China Internet Network Information Center in July 2025, the number of internet users in China reached more than 1.12 billion by June 2025, with an internet penetration rate of 79.7%. Among them, about 0.98 billion were users of online shopping platforms, accounting for 86.9% of all internet users. Meanwhile, the popularity of livestream shopping has turned interactive online shopping into a new form of digital entertainment."]}, {"id": "u2_s4_p2", "buf": ["E-commerce platforms in China offer access to an enormous variety of products and provide highly efficient delivery services—including one-hour and same-day options—that greatly enhance the consumer experience."], "text": "E-commerce platforms in China offer access to an enormous variety of products and provide highly efficient delivery services—including one-hour and same-day options—that greatly enhance the consumer experience.", "chunks": ["E-commerce platforms in China offer access to an enormous variety of products and provide highly efficient delivery services—including one-hour and same-day options—that greatly enhance the consumer experience."]}, {"id": "u2_s4_p3", "buf": ["The rapid growth of online shopping in China is closely tied to the security and reliability of the country's leading third-party payment platforms. These platforms offer consumers convenient and secure payment solutions, boosting confidence in online transactions. Their robust infrastructure enables users to shop and pay safely, making online shopping more accessible and fostering the widespread adoption of online retail across the nation."], "text": "The rapid growth of online shopping in China is closely tied to the security and reliability of the country's leading third-party payment platforms. These platforms offer consumers convenient and secure payment solutions, boosting confidence in online transactions. Their robust infrastructure enables users to shop and pay safely, making online shopping more accessible and fostering the widespread adoption of online retail across the nation.", "chunks": ["The rapid growth of online shopping in China is closely tied to the security and reliability of the country's leading third-party payment platforms. These platforms offer consumers convenient and secure payment solutions, boosting confidence in online transactions. Their robust infrastructure enables users to shop and pay safely, making online shopping more accessible and fostering the widespread adoption of online retail across the nation."]}]}, {"id": "u2_s5", "title": "虚拟博物馆展览", "paras": [{"id": "u2_s5_p1", "buf": ["In recent years, virtual museum exhibitions have become a major trend in China's cultural sector, reflecting the growing demand for virtual museum experiences. Many museums in China have launched online exhibitions, virtual courses, interactive mini programmes, and other digital services to enrich the public's cultural life."], "text": "In recent years, virtual museum exhibitions have become a major trend in China's cultural sector, reflecting the growing demand for virtual museum experiences. Many museums in China have launched online exhibitions, virtual courses, interactive mini programmes, and other digital services to enrich the public's cultural life.", "chunks": ["In recent years, virtual museum exhibitions have become a major trend in China's cultural sector, reflecting the growing demand for virtual museum experiences. Many museums in China have launched online exhibitions, virtual courses, interactive mini programmes, and other digital services to enrich the public's cultural life."]}, {"id": "u2_s5_p2", "buf": ["The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Museum Exhibition. These tools enable the public to visit the Palace Museum and explore its collections without leaving home. Even after offline exhibitions end, users can continue to enjoy them via the official website or the museum's apps."], "text": "The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Museum Exhibition. These tools enable the public to visit the Palace Museum and explore its collections without leaving home. Even after offline exhibitions end, users can continue to enjoy them via the official website or the museum's apps.", "chunks": ["The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Museum Exhibition. These tools enable the public to visit the Palace Museum and explore its collections without leaving home. Even after offline exhibitions end, users can continue to enjoy them via the official website or the museum's apps."]}, {"id": "u2_s5_p3", "buf": ["The Shanghai Museum has also embraced digital technology in its exhibition The Ferryman of Ink World (丹青宝筏): Dong Qichang's Calligraphy and Painting Art. By integrating virtual elements into the display, the museum enhances both scholarly interpretation and visitor engagement. Interactive features such as a digital timeline and a virtual map allow visitors to explore Dong Qichang's life, artistic development, and travels, exemplifying the museum's innovative approach to combining traditional art scholarship with digital humanities practices."], "text": "The Shanghai Museum has also embraced digital technology in its exhibition The Ferryman of Ink World (丹青宝筏): Dong Qichang's Calligraphy and Painting Art. By integrating virtual elements into the display, the museum enhances both scholarly interpretation and visitor engagement. Interactive features such as a digital timeline and a virtual map allow visitors to explore Dong Qichang's life, artistic development, and travels, exemplifying the museum's innovative approach to combining traditional art scholarship with digital humanities practices.", "chunks": ["The Shanghai Museum has also embraced digital technology in its exhibition The Ferryman of Ink World (丹青宝筏): Dong Qichang's Calligraphy and Painting Art. By integrating virtual elements into the display, the museum enhances both scholarly interpretation and visitor engagement. Interactive features such as a digital timeline and a virtual map allow visitors to explore Dong Qichang's life, artistic development, and travels, exemplifying the museum's innovative approach to combining traditional art scholarship with digital humanities practices."]}, {"id": "u2_s5_p4", "buf": ["The Terracotta Warriors Museum in Xi'an also offers immersive online experiences. Through virtual tours, visitors can explore the Terracotta Warriors from multiple angles, gaining a deeper understanding of the relics while learning about their history and significance."], "text": "The Terracotta Warriors Museum in Xi'an also offers immersive online experiences. Through virtual tours, visitors can explore the Terracotta Warriors from multiple angles, gaining a deeper understanding of the relics while learning about their history and significance.", "chunks": ["The Terracotta Warriors Museum in Xi'an also offers immersive online experiences. Through virtual tours, visitors can explore the Terracotta Warriors from multiple angles, gaining a deeper understanding of the relics while learning about their history and significance."]}, {"id": "u2_s5_p5", "buf": ["Another prominent example is the Mogao Grottoes in Dunhuang, where the Digital Dunhuang initiative has been applied to preserve and share the artistic legacy of the site. This project provides virtual access to many caves through high-resolution images and panoramic views, enabling users to explore intricate murals and sculptures in great detail. Cutting-edge virtual reality experiences further immerse visitors in the artistic and historical heritage of these ancient treasures."], "text": "Another prominent example is the Mogao Grottoes in Dunhuang, where the Digital Dunhuang initiative has been applied to preserve and share the artistic legacy of the site. This project provides virtual access to many caves through high-resolution images and panoramic views, enabling users to explore intricate murals and sculptures in great detail. Cutting-edge virtual reality experiences further immerse visitors in the artistic and historical heritage of these ancient treasures.", "chunks": ["Another prominent example is the Mogao Grottoes in Dunhuang, where the Digital Dunhuang initiative has been applied to preserve and share the artistic legacy of the site. This project provides virtual access to many caves through high-resolution images and panoramic views, enabling users to explore intricate murals and sculptures in great detail. Cutting-edge virtual reality experiences further immerse visitors in the artistic and historical heritage of these ancient treasures."]}, {"id": "u2_s5_p6", "buf": ["At the same time, major internet platforms in China launched livestreamed museum tours, with dozens of cultural institutions across the country taking part. The Potala Palace (布达拉宫) had its first live webcast in 2020, taking nearly one million viewers inside areas that usually remain closed to the public. Over the course of an hour, viewers could see the site of its digitisation work for ancient manuscripts and the golden-roofed chambers. The Xi'an Beilin Museum attracted around 400,000 viewers during a single livestream. The Palace Museum streamed its spring scenery on multiple online platforms, showcasing the museum's beauty before and after opening hours, which attracted nearly 10 million viewers on a single platform."], "text": "At the same time, major internet platforms in China launched livestreamed museum tours, with dozens of cultural institutions across the country taking part. The Potala Palace (布达拉宫) had its first live webcast in 2020, taking nearly one million viewers inside areas that usually remain closed to the public. Over the course of an hour, viewers could see the site of its digitisation work for ancient manuscripts and the golden-roofed chambers. The Xi'an Beilin Museum attracted around 400,000 viewers during a single livestream. The Palace Museum streamed its spring scenery on multiple online platforms, showcasing the museum's beauty before and after opening hours, which attracted nearly 10 million viewers on a single platform.", "chunks": ["At the same time, major internet platforms in China launched livestreamed museum tours, with dozens of cultural institutions across the country taking part. The Potala Palace (布达拉宫) had its first live webcast in 2020, taking nearly one million viewers inside areas that usually remain closed to the public. Over the course of an hour, viewers could see the site of its digitisation work for ancient manuscripts and the golden-roofed chambers. The Xi'an Beilin Museum attracted around 400,000 viewers during a single livestream. The Palace Museum streamed its spring scenery on multiple online platforms, showcasing the museum's beauty before and after opening hours, which attracted nearly 10 million viewers on a single platform."]}, {"id": "u2_s5_p7", "buf": ["Unlike on-site visits, virtual exhibitions are free from crowds, allowing visitors to enjoy exhibits at their own pace and explore each piece closely from all angles. With the development of technology, virtual exhibitions are set to become the new normal."], "text": "Unlike on-site visits, virtual exhibitions are free from crowds, allowing visitors to enjoy exhibits at their own pace and explore each piece closely from all angles. With the development of technology, virtual exhibitions are set to become the new normal.", "chunks": ["Unlike on-site visits, virtual exhibitions are free from crowds, allowing visitors to enjoy exhibits at their own pace and explore each piece closely from all angles. With the development of technology, virtual exhibitions are set to become the new normal."]}]}]}, {"id": "u3", "title": "旅游资源与景点", "sections": [{"id": "u3_s0", "title": "旅游资源与景点", "paras": [{"id": "u3_s0_p1", "buf": ["China is rich in tourism resources, with many unique and famous tourist cities, each with its own cultural background and historical stories. From the history-rich capital Beijing in the north to the picturesque city of Guilin in the south, from the modern metropolis of Shanghai in the east to the majestic Qinghai–Xizang Plateau in the west, China's tourist attractions encompass a broad range of natural and cultural landscapes. These rich tourism resources not only provide ample leisure travel opportunities for Chinese people to relax and enjoy the beauty of nature and culture, but they also attract a large number of international tourists to China."], "text": "China is rich in tourism resources, with many unique and famous tourist cities, each with its own cultural background and historical stories. From the history-rich capital Beijing in the north to the picturesque city of Guilin in the south, from the modern metropolis of Shanghai in the east to the majestic Qinghai–Xizang Plateau in the west, China's tourist attractions encompass a broad range of natural and cultural landscapes. These rich tourism resources not only provide ample leisure travel opportunities for Chinese people to relax and enjoy the beauty of nature and culture, but they also attract a large number of international tourists to China.", "chunks": ["China is rich in tourism resources, with many unique and famous tourist cities, each with its own cultural background and historical stories. From the history-rich capital Beijing in the north to the picturesque city of Guilin in the south, from the modern metropolis of Shanghai in the east to the majestic Qinghai–Xizang Plateau in the west, China's tourist attractions encompass a broad range of natural and cultural landscapes. These rich tourism resources not only provide ample leisure travel opportunities for Chinese people to relax and enjoy the beauty of nature and culture, but they also attract a large number of international tourists to China."]}]}, {"id": "u3_s1", "title": "主要旅游城市", "paras": [{"id": "u3_s1_p1", "buf": ["By the end of 2023, the number of cities in China had reached 694, each possessing its own distinctive characteristics."], "text": "By the end of 2023, the number of cities in China had reached 694, each possessing its own distinctive characteristics.", "chunks": ["By the end of 2023, the number of cities in China had reached 694, each possessing its own distinctive characteristics."]}]}, {"id": "u3_s2", "title": "北京", "paras": [{"id": "u3_s2_p1", "buf": ["Beijing, China's capital, is located in the northern part of the North China Plain. This vibrant, modern metropolis is rich in cultural relics, historic sites, and captivating landscapes. Cultural festivals and theatrical performances are among its major attractions."], "text": "Beijing, China's capital, is located in the northern part of the North China Plain. This vibrant, modern metropolis is rich in cultural relics, historic sites, and captivating landscapes. Cultural festivals and theatrical performances are among its major attractions.", "chunks": ["Beijing, China's capital, is located in the northern part of the North China Plain. This vibrant, modern metropolis is rich in cultural relics, historic sites, and captivating landscapes. Cultural festivals and theatrical performances are among its major attractions."]}, {"id": "u3_s2_p2", "buf": ["The Imperial Palace, a vast ancient architectural complex located at the centre of Beijing, covers an area of more than 720,000 square metres, and measures 961 metres in length and 753 metres in width. It is regarded as one of the finest examples of traditional Chinese architecture. Until 1924, when the last emperor of China was expelled from the Inner Court, 14 emperors of the Ming Dynasty and 10 emperors of the Qing Dynasty reigned in the palace. Having been the imperial palace for nearly five centuries, it houses numerous treasures and curiosities. The Imperial Palace of Beijing was inscribed on the World Heritage List in 1987. It remains one of the most popular tourist attractions in the world."], "text": "The Imperial Palace, a vast ancient architectural complex located at the centre of Beijing, covers an area of more than 720,000 square metres, and measures 961 metres in length and 753 metres in width. It is regarded as one of the finest examples of traditional Chinese architecture. Until 1924, when the last emperor of China was expelled from the Inner Court, 14 emperors of the Ming Dynasty and 10 emperors of the Qing Dynasty reigned in the palace. Having been the imperial palace for nearly five centuries, it houses numerous treasures and curiosities. The Imperial Palace of Beijing was inscribed on the World Heritage List in 1987. It remains one of the most popular tourist attractions in the world.", "chunks": ["The Imperial Palace, a vast ancient architectural complex located at the centre of Beijing, covers an area of more than 720,000 square metres, and measures 961 metres in length and 753 metres in width. It is regarded as one of the finest examples of traditional Chinese architecture. Until 1924, when the last emperor of China was expelled from the Inner Court, 14 emperors of the Ming Dynasty and 10 emperors of the Qing Dynasty reigned in the palace. Having been the imperial palace for nearly five centuries, it houses numerous treasures and curiosities. The Imperial Palace of Beijing was inscribed on the World Heritage List in 1987. It remains one of the most popular tourist attractions in the world."]}, {"id": "u3_s2_p3", "buf": ["Tian'anmen Square attracts tens of thousands of visitors each day. The imposing Tian'anmen Gate stands at its northern end. The five-star red flag flies high above, and the Monument to the People's Heroes (人民英雄纪念碑) is located at the centre of the square. To the west is the Great Hall of the People (人民大会堂), and to the east is the National Museum of China."], "text": "Tian'anmen Square attracts tens of thousands of visitors each day. The imposing Tian'anmen Gate stands at its northern end. The five-star red flag flies high above, and the Monument to the People's Heroes (人民英雄纪念碑) is located at the centre of the square. To the west is the Great Hall of the People (人民大会堂), and to the east is the National Museum of China.", "chunks": ["Tian'anmen Square attracts tens of thousands of visitors each day. The imposing Tian'anmen Gate stands at its northern end. The five-star red flag flies high above, and the Monument to the People's Heroes (人民英雄纪念碑) is located at the centre of the square. To the west is the Great Hall of the People (人民大会堂), and to the east is the National Museum of China."]}, {"id": "u3_s2_p4", "buf": ["The Temple of Heaven, a masterpiece of architecture and landscape design, is situated in southern Beijing. It was once the place where emperors of the Ming and Qing dynasties worshipped Heaven and prayed for good harvests. The temple's symbolic layout and design embody the wisdom and ingenuity of ancient Chinese architecture. The complex is enclosed by two walls. The corners on the south side of these walls are all right angles, while those on the north side feature rounded curves, which reflects the ancient Chinese belief that Heaven is round and Earth is square. The higher elevation of the northern wall symbolises the supremacy of Heaven over Earth. The two enclosing walls divide the temple into inner and outer sections. Today, the Temple of Heaven serves as a cultural museum illustrating the imperial rites of offering sacrifices to Heaven, integrating architecture, aesthetics, acoustics (声学), astronomy, calendar studies, music, and dance into a harmonious whole. It is an important window into China's history."], "text": "The Temple of Heaven, a masterpiece of architecture and landscape design, is situated in southern Beijing. It was once the place where emperors of the Ming and Qing dynasties worshipped Heaven and prayed for good harvests. The temple's symbolic layout and design embody the wisdom and ingenuity of ancient Chinese architecture. The complex is enclosed by two walls. The corners on the south side of these walls are all right angles, while those on the north side feature rounded curves, which reflects the ancient Chinese belief that Heaven is round and Earth is square. The higher elevation of the northern wall symbolises the supremacy of Heaven over Earth. The two enclosing walls divide the temple into inner and outer sections. Today, the Temple of Heaven serves as a cultural museum illustrating the imperial rites of offering sacrifices to Heaven, integrating architecture, aesthetics, acoustics (声学), astronomy, calendar studies, music, and dance into a harmonious whole. It is an important window into China's history.", "chunks": ["The Temple of Heaven, a masterpiece of architecture and landscape design, is situated in southern Beijing. It was once the place where emperors of the Ming and Qing dynasties worshipped Heaven and prayed for good harvests. The temple's symbolic layout and design embody the wisdom and ingenuity of ancient Chinese architecture. The complex is enclosed by two walls. The corners on the south side of these walls are all right angles, while those on the north side feature rounded curves, which reflects the ancient Chinese belief that Heaven is round and Earth is square. The higher elevation of the northern wall symbolises the supremacy of Heaven over Earth. The two enclosing walls divide the temple into inner and outer sections. Today, the Temple of Heaven serves as a cultural museum illustrating the imperial rites of offering sacrifices to Heaven, integrating architecture, aesthetics, acoustics (声学), astronomy, calendar studies, music, and dance into a harmonious whole. It is an important window into China's history."]}, {"id": "u3_s2_p5", "buf": ["The Summer Palace lies in the northwest of Beijing. Covering an area of approximately 300 hectares, it is one of the largest imperial gardens in the world. The Summer Palace features the Longevity Hill (万寿山) and Kunming Lake, and contains more than 3,000 ancient structures, including pavilions, bridges, corridors, halls, and palaces, making it a veritable museum of classical Chinese garden architecture."], "text": "The Summer Palace lies in the northwest of Beijing. Covering an area of approximately 300 hectares, it is one of the largest imperial gardens in the world. The Summer Palace features the Longevity Hill (万寿山) and Kunming Lake, and contains more than 3,000 ancient structures, including pavilions, bridges, corridors, halls, and palaces, making it a veritable museum of classical Chinese garden architecture.", "chunks": ["The Summer Palace lies in the northwest of Beijing. Covering an area of approximately 300 hectares, it is one of the largest imperial gardens in the world. The Summer Palace features the Longevity Hill (万寿山) and Kunming Lake, and contains more than 3,000 ancient structures, including pavilions, bridges, corridors, halls, and palaces, making it a veritable museum of classical Chinese garden architecture."]}]}, {"id": "u3_s3", "title": "上海", "paras": [{"id": "u3_s3_p1", "buf": ["As China's premier financial, trade, and industrial hub, Shanghai is often described as a dazzling pearl on the east coast, where the golden channel of the Yangtze River flows into the sea."], "text": "As China's premier financial, trade, and industrial hub, Shanghai is often described as a dazzling pearl on the east coast, where the golden channel of the Yangtze River flows into the sea.", "chunks": ["As China's premier financial, trade, and industrial hub, Shanghai is often described as a dazzling pearl on the east coast, where the golden channel of the Yangtze River flows into the sea."]}, {"id": "u3_s3_p2", "buf": ["Home to famous landmarks such as the Bund (外滩) and Nanjing Road, Shanghai is one of China's most international metropolises, attracting substantial foreign investment and numerous tourists. Since the 1990s, Shanghai has strengthened its leading role in technological innovation, finance, and cultural development, establishing several zones such as the Lujiazui Finance and Trade Zone and the Zhangjiang Hi-Tech Park."], "text": "Home to famous landmarks such as the Bund (外滩) and Nanjing Road, Shanghai is one of China's most international metropolises, attracting substantial foreign investment and numerous tourists. Since the 1990s, Shanghai has strengthened its leading role in technological innovation, finance, and cultural development, establishing several zones such as the Lujiazui Finance and Trade Zone and the Zhangjiang Hi-Tech Park.", "chunks": ["Home to famous landmarks such as the Bund (外滩) and Nanjing Road, Shanghai is one of China's most international metropolises, attracting substantial foreign investment and numerous tourists. Since the 1990s, Shanghai has strengthened its leading role in technological innovation, finance, and cultural development, establishing several zones such as the Lujiazui Finance and Trade Zone and the Zhangjiang Hi-Tech Park."]}]}, {"id": "u3_s4", "title": "杭州", "paras": [{"id": "u3_s4_p1", "buf": ["Situated on the southern wing of the Yangtze River Delta, Hangzhou was the capital of the Wuyue Kingdom during the Five Dynasties and Ten Kingdoms period and later became the capital of the Southern Song Dynasty. During the Yuan Dynasty, the Italian explorer Marco Polo was deeply impressed by the beauty of the city and described it as \"beyond dispute the finest and the noblest in the world\"."], "text": "Situated on the southern wing of the Yangtze River Delta, Hangzhou was the capital of the Wuyue Kingdom during the Five Dynasties and Ten Kingdoms period and later became the capital of the Southern Song Dynasty. During the Yuan Dynasty, the Italian explorer Marco Polo was deeply impressed by the beauty of the city and described it as \"beyond dispute the finest and the noblest in the world\".", "chunks": ["Situated on the southern wing of the Yangtze River Delta, Hangzhou was the capital of the Wuyue Kingdom during the Five Dynasties and Ten Kingdoms period and later became the capital of the Southern Song Dynasty. During the Yuan Dynasty, the Italian explorer Marco Polo was deeply impressed by the beauty of the city and described it as \"beyond dispute the finest and the noblest in the world\"."]}, {"id": "u3_s4_p2", "buf": ["Hangzhou is renowned for its surrounding hills and beautiful scenery, especially the West Lake. Other popular tourist attractions include the Six Harmonies Pagoda (六和塔) and the Lingyin Temple. Hangzhou is also known as one of China's major centres of silk production. Additionally, the city is famous for its Longjing tea, which has a refreshing aroma, rich flavour, pleasing leaf shape, and vibrant green colour."], "text": "Hangzhou is renowned for its surrounding hills and beautiful scenery, especially the West Lake. Other popular tourist attractions include the Six Harmonies Pagoda (六和塔) and the Lingyin Temple. Hangzhou is also known as one of China's major centres of silk production. Additionally, the city is famous for its Longjing tea, which has a refreshing aroma, rich flavour, pleasing leaf shape, and vibrant green colour.", "chunks": ["Hangzhou is renowned for its surrounding hills and beautiful scenery, especially the West Lake. Other popular tourist attractions include the Six Harmonies Pagoda (六和塔) and the Lingyin Temple. Hangzhou is also known as one of China's major centres of silk production. Additionally, the city is famous for its Longjing tea, which has a refreshing aroma, rich flavour, pleasing leaf shape, and vibrant green colour."]}, {"id": "u3_s4_p3", "buf": ["In addition to its rich history and cultural heritage, Hangzhou is also a model of modern urban development in China. Its high-tech and e-commerce industries are developing rapidly, making the city a key engine of China's economic growth. Hangzhou is one of the centres of e-commerce in China and is home to one of the world's largest online trading enterprises, through which millions of merchants and consumers worldwide conduct transactions every day. Specialised industrial parks have been built to make full use of the city's digital-economy advantages and platform-based ecosystem, and to connect enterprises with multiple international e-commerce platforms and global markets."], "text": "In addition to its rich history and cultural heritage, Hangzhou is also a model of modern urban development in China. Its high-tech and e-commerce industries are developing rapidly, making the city a key engine of China's economic growth. Hangzhou is one of the centres of e-commerce in China and is home to one of the world's largest online trading enterprises, through which millions of merchants and consumers worldwide conduct transactions every day. Specialised industrial parks have been built to make full use of the city's digital-economy advantages and platform-based ecosystem, and to connect enterprises with multiple international e-commerce platforms and global markets.", "chunks": ["In addition to its rich history and cultural heritage, Hangzhou is also a model of modern urban development in China. Its high-tech and e-commerce industries are developing rapidly, making the city a key engine of China's economic growth. Hangzhou is one of the centres of e-commerce in China and is home to one of the world's largest online trading enterprises, through which millions of merchants and consumers worldwide conduct transactions every day. Specialised industrial parks have been built to make full use of the city's digital-economy advantages and platform-based ecosystem, and to connect enterprises with multiple international e-commerce platforms and global markets."]}]}, {"id": "u3_s5", "title": "台北", "paras": [{"id": "u3_s5_p1", "buf": ["Taipei, located in the northern part of Taiwan Island, is the political, economic, and cultural centre of the region. Taipei is a vibrant and diverse city, rich in history, cultural heritage, cuisine, and nightlife."], "text": "Taipei, located in the northern part of Taiwan Island, is the political, economic, and cultural centre of the region. Taipei is a vibrant and diverse city, rich in history, cultural heritage, cuisine, and nightlife.", "chunks": ["Taipei, located in the northern part of Taiwan Island, is the political, economic, and cultural centre of the region. Taipei is a vibrant and diverse city, rich in history, cultural heritage, cuisine, and nightlife."]}, {"id": "u3_s5_p2", "buf": ["Taipei is home to many historical monuments and museums, such as the Taipei Palace Museum and the Taipei Zhongshan Hall. These sites showcase Taiwan's history and culture, making them must-visit places for those interested in the local heritage. In addition, Taipei features well-preserved historical neighbourhoods such as Yongkang Street and Dihua Street, where traditional architecture and culture remain largely intact."], "text": "Taipei is home to many historical monuments and museums, such as the Taipei Palace Museum and the Taipei Zhongshan Hall. These sites showcase Taiwan's history and culture, making them must-visit places for those interested in the local heritage. In addition, Taipei features well-preserved historical neighbourhoods such as Yongkang Street and Dihua Street, where traditional architecture and culture remain largely intact.", "chunks": ["Taipei is home to many historical monuments and museums, such as the Taipei Palace Museum and the Taipei Zhongshan Hall. These sites showcase Taiwan's history and culture, making them must-visit places for those interested in the local heritage. In addition, Taipei features well-preserved historical neighbourhoods such as Yongkang Street and Dihua Street, where traditional architecture and culture remain largely intact."]}, {"id": "u3_s5_p3", "buf": ["Taipei 101, formerly the Taipei Financial Center, is one of the most iconic landmarks of Taipei. The skyscraper has 101 storeys above ground and reaches a height of 508 metres. At the time of its official opening in 2004, it ranked as the world's tallest building, surpassing the Petronas Twin Towers in Malaysia. The main section of the building consists of eight modules, each eight storeys high—eight being an auspicious number in Chinese culture. The building also reflects its distinctive Chinese character in its resemblance to a stalk of bamboo, symbolising the elegance and noble spirit long associated with bamboo in Chinese culture."], "text": "Taipei 101, formerly the Taipei Financial Center, is one of the most iconic landmarks of Taipei. The skyscraper has 101 storeys above ground and reaches a height of 508 metres. At the time of its official opening in 2004, it ranked as the world's tallest building, surpassing the Petronas Twin Towers in Malaysia. The main section of the building consists of eight modules, each eight storeys high—eight being an auspicious number in Chinese culture. The building also reflects its distinctive Chinese character in its resemblance to a stalk of bamboo, symbolising the elegance and noble spirit long associated with bamboo in Chinese culture.", "chunks": ["Taipei 101, formerly the Taipei Financial Center, is one of the most iconic landmarks of Taipei. The skyscraper has 101 storeys above ground and reaches a height of 508 metres. At the time of its official opening in 2004, it ranked as the world's tallest building, surpassing the Petronas Twin Towers in Malaysia. The main section of the building consists of eight modules, each eight storeys high—eight being an auspicious number in Chinese culture. The building also reflects its distinctive Chinese character in its resemblance to a stalk of bamboo, symbolising the elegance and noble spirit long associated with bamboo in Chinese culture."]}, {"id": "u3_s5_p4", "buf": ["Taipei also has many natural landscapes, such as the Yangmingshan Park and the Danshui River."], "text": "Taipei also has many natural landscapes, such as the Yangmingshan Park and the Danshui River.", "chunks": ["Taipei also has many natural landscapes, such as the Yangmingshan Park and the Danshui River."]}]}, {"id": "u3_s6", "title": "西安", "paras": [{"id": "u3_s6_p1", "buf": ["Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its surrounding area are often regarded as China's \"museum of nature and history\". Xi'an features the ruins of several grand imperial palaces, such as the Epang Palace from the Qin Dynasty, the Weiyang Palace from the Han Dynasty, and the Daming Palace and the Huaqing Palace from the Tang Dynasty. The city also contains numerous other historic monuments, including the Great Mosque (大清真寺), the Big Wild Goose Pagoda (大雁塔), the Small Wild Goose Pagoda (小雁塔), and the Bell and Drum Towers. The area also features a concentration of imperial tombs from the Qin, Han, and Tang dynasties. The most famous of these is the Mausoleum of Emperor Qin Shihuang, a vast area which includes the world-famous Terracotta Warriors and Horses—often referred to as the \"Eighth Wonder of the World\"."], "text": "Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its surrounding area are often regarded as China's \"museum of nature and history\". Xi'an features the ruins of several grand imperial palaces, such as the Epang Palace from the Qin Dynasty, the Weiyang Palace from the Han Dynasty, and the Daming Palace and the Huaqing Palace from the Tang Dynasty. The city also contains numerous other historic monuments, including the Great Mosque (大清真寺), the Big Wild Goose Pagoda (大雁塔), the Small Wild Goose Pagoda (小雁塔), and the Bell and Drum Towers. The area also features a concentration of imperial tombs from the Qin, Han, and Tang dynasties. The most famous of these is the Mausoleum of Emperor Qin Shihuang, a vast area which includes the world-famous Terracotta Warriors and Horses—often referred to as the \"Eighth Wonder of the World\".", "chunks": ["Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its surrounding area are often regarded as China's \"museum of nature and history\". Xi'an features the ruins of several grand imperial palaces, such as the Epang Palace from the Qin Dynasty, the Weiyang Palace from the Han Dynasty, and the Daming Palace and the Huaqing Palace from the Tang Dynasty. The city also contains numerous other historic monuments, including the Great Mosque (大清真寺), the Big Wild Goose Pagoda (大雁塔), the Small Wild Goose Pagoda (小雁塔), and the Bell and Drum Towers. The area also features a concentration of imperial tombs from the Qin, Han, and Tang dynasties. The most famous of these is the Mausoleum of Emperor Qin Shihuang, a vast area which includes the world-famous Terracotta Warriors and Horses—often referred to as the \"Eighth Wonder of the World\"."]}, {"id": "u3_s6_p2", "buf": ["Following the traditional belief of \"serving the dead as one serves the living (事死如事生)\", Emperor Qin Shihuang recreated the luxury and splendour of his lifetime within his tomb, commissioning a magnificent imperial mausoleum for himself. Being fully aware of the importance of armed forces, he ordered the creation of life-sized terracotta figures for burial near his tomb to guard his spirit. Thus, the Terracotta Army was formed."], "text": "Following the traditional belief of \"serving the dead as one serves the living (事死如事生)\", Emperor Qin Shihuang recreated the luxury and splendour of his lifetime within his tomb, commissioning a magnificent imperial mausoleum for himself. Being fully aware of the importance of armed forces, he ordered the creation of life-sized terracotta figures for burial near his tomb to guard his spirit. Thus, the Terracotta Army was formed.", "chunks": ["Following the traditional belief of \"serving the dead as one serves the living (事死如事生)\", Emperor Qin Shihuang recreated the luxury and splendour of his lifetime within his tomb, commissioning a magnificent imperial mausoleum for himself. Being fully aware of the importance of armed forces, he ordered the creation of life-sized terracotta figures for burial near his tomb to guard his spirit. Thus, the Terracotta Army was formed."]}, {"id": "u3_s6_p3", "buf": ["In 1974, farmers digging a well accidentally unearthed terracotta fragments, leading to the subsequent discovery of the Terracotta Army. Archaeologists excavated a vault containing thousands of terracotta warriors and horses that had remained entombed for over 2,000 years. The discovery is considered one of the most significant archaeological finds of the 20th century. To date, three pits covering more than 20,000 square metres have been unearthed, containing about 8,000 life-sized warriors that demonstrate the military power of Emperor Qin Shihuang."], "text": "In 1974, farmers digging a well accidentally unearthed terracotta fragments, leading to the subsequent discovery of the Terracotta Army. Archaeologists excavated a vault containing thousands of terracotta warriors and horses that had remained entombed for over 2,000 years. The discovery is considered one of the most significant archaeological finds of the 20th century. To date, three pits covering more than 20,000 square metres have been unearthed, containing about 8,000 life-sized warriors that demonstrate the military power of Emperor Qin Shihuang.", "chunks": ["In 1974, farmers digging a well accidentally unearthed terracotta fragments, leading to the subsequent discovery of the Terracotta Army. Archaeologists excavated a vault containing thousands of terracotta warriors and horses that had remained entombed for over 2,000 years. The discovery is considered one of the most significant archaeological finds of the 20th century. To date, three pits covering more than 20,000 square metres have been unearthed, containing about 8,000 life-sized warriors that demonstrate the military power of Emperor Qin Shihuang."]}]}, {"id": "u3_s7", "title": "拉萨", "paras": [{"id": "u3_s7_p1", "buf": ["Lhasa, the capital of the Xizang Autonomous Region, is one of the highest cities in the world, with an elevation of approximately 3,650 metres. Its recorded history dates back about 1,300 years. Located in a mountain-encircled basin, Lhasa offers breathtaking scenery and a unique spiritual atmosphere. The city features a combination of traditional and modern life, with prayer wheels (转经筒) standing alongside gleaming streetlights, creating a striking sight for visitors."], "text": "Lhasa, the capital of the Xizang Autonomous Region, is one of the highest cities in the world, with an elevation of approximately 3,650 metres. Its recorded history dates back about 1,300 years. Located in a mountain-encircled basin, Lhasa offers breathtaking scenery and a unique spiritual atmosphere. The city features a combination of traditional and modern life, with prayer wheels (转经筒) standing alongside gleaming streetlights, creating a striking sight for visitors.", "chunks": ["Lhasa, the capital of the Xizang Autonomous Region, is one of the highest cities in the world, with an elevation of approximately 3,650 metres. Its recorded history dates back about 1,300 years. Located in a mountain-encircled basin, Lhasa offers breathtaking scenery and a unique spiritual atmosphere. The city features a combination of traditional and modern life, with prayer wheels (转经筒) standing alongside gleaming streetlights, creating a striking sight for visitors."]}, {"id": "u3_s7_p2", "buf": ["The Potala Palace is located on the Red Hill, in the northwest of Lhasa. It was originally built in the seventh century during the reign of Songtsen Gampo (松赞干布), who established the Tubo Kingdom (吐蕃王国) in today's Xizang and made Lhasa its capital. The Tang emperor sent Princess Wencheng (文成公主) to marry Songtsen Gampo. To welcome the princess, Songtsen Gampo built the Potala Palace. It was later destroyed in wars and natural disasters and was rebuilt in the 17th century. The present Potala Palace is about 115 metres high with 13 storeys. The entire building is made of stone and wood, with walls being three metres thick on average. The palace houses a large collection of sculptures, murals, scriptures, and other valuable cultural relics."], "text": "The Potala Palace is located on the Red Hill, in the northwest of Lhasa. It was originally built in the seventh century during the reign of Songtsen Gampo (松赞干布), who established the Tubo Kingdom (吐蕃王国) in today's Xizang and made Lhasa its capital. The Tang emperor sent Princess Wencheng (文成公主) to marry Songtsen Gampo. To welcome the princess, Songtsen Gampo built the Potala Palace. It was later destroyed in wars and natural disasters and was rebuilt in the 17th century. The present Potala Palace is about 115 metres high with 13 storeys. The entire building is made of stone and wood, with walls being three metres thick on average. The palace houses a large collection of sculptures, murals, scriptures, and other valuable cultural relics.", "chunks": ["The Potala Palace is located on the Red Hill, in the northwest of Lhasa. It was originally built in the seventh century during the reign of Songtsen Gampo (松赞干布), who established the Tubo Kingdom (吐蕃王国) in today's Xizang and made Lhasa its capital. The Tang emperor sent Princess Wencheng (文成公主) to marry Songtsen Gampo. To welcome the princess, Songtsen Gampo built the Potala Palace. It was later destroyed in wars and natural disasters and was rebuilt in the 17th century. The present Potala Palace is about 115 metres high with 13 storeys. The entire building is made of stone and wood, with walls being three metres thick on average. The palace houses a large collection of sculptures, murals, scriptures, and other valuable cultural relics."]}]}, {"id": "u3_s8", "title": "自然景观", "paras": [{"id": "u3_s8_p1", "buf": ["As well as its significant cultural and historical attractions, China has a great many breathtaking natural attractions. Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer spectacular mountain scenery, while the Jiuzhaigou Valley Scenic and Historic Interest Area, the Zhangjiajie National Forest Park, and the Sanjiangyuan (Three-River-Source) National Park boast some of the country's most stunning natural landscapes."], "text": "As well as its significant cultural and historical attractions, China has a great many breathtaking natural attractions. Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer spectacular mountain scenery, while the Jiuzhaigou Valley Scenic and Historic Interest Area, the Zhangjiajie National Forest Park, and the Sanjiangyuan (Three-River-Source) National Park boast some of the country's most stunning natural landscapes.", "chunks": ["As well as its significant cultural and historical attractions, China has a great many breathtaking natural attractions. Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer spectacular mountain scenery, while the Jiuzhaigou Valley Scenic and Historic Interest Area, the Zhangjiajie National Forest Park, and the Sanjiangyuan (Three-River-Source) National Park boast some of the country's most stunning natural landscapes."]}, {"id": "u3_s8_p2", "buf": ["Mount Huangshan, one of the most famous scenic mountain areas in China, is renowned for its five wonders: peculiar pines (奇松), grotesque rocks (怪石), a sea of clouds, hot springs, and winter snow. Mount Huangshan is not only a masterpiece of natural forces, but it also embodies China's rich cultural heritage. Since ancient times, many literati have celebrated the mountain in their works, making it an important symbol of Chinese art and culture."], "text": "Mount Huangshan, one of the most famous scenic mountain areas in China, is renowned for its five wonders: peculiar pines (奇松), grotesque rocks (怪石), a sea of clouds, hot springs, and winter snow. Mount Huangshan is not only a masterpiece of natural forces, but it also embodies China's rich cultural heritage. Since ancient times, many literati have celebrated the mountain in their works, making it an important symbol of Chinese art and culture.", "chunks": ["Mount Huangshan, one of the most famous scenic mountain areas in China, is renowned for its five wonders: peculiar pines (奇松), grotesque rocks (怪石), a sea of clouds, hot springs, and winter snow. Mount Huangshan is not only a masterpiece of natural forces, but it also embodies China's rich cultural heritage. Since ancient times, many literati have celebrated the mountain in their works, making it an important symbol of Chinese art and culture."]}, {"id": "u3_s8_p3", "buf": ["As the foremost of the Five Great Mountains of China, Mount Taishan is not only a treasure of natural beauty but also a sacred site in Chinese culture. Historically, Mount Taishan was a place for emperors to hold worship ceremonies and where poets and writers came to seek inspiration. On Mount Taishan, visitors can enjoy stone inscriptions and temples, experiencing China's long history and rich culture."], "text": "As the foremost of the Five Great Mountains of China, Mount Taishan is not only a treasure of natural beauty but also a sacred site in Chinese culture. Historically, Mount Taishan was a place for emperors to hold worship ceremonies and where poets and writers came to seek inspiration. On Mount Taishan, visitors can enjoy stone inscriptions and temples, experiencing China's long history and rich culture.", "chunks": ["As the foremost of the Five Great Mountains of China, Mount Taishan is not only a treasure of natural beauty but also a sacred site in Chinese culture. Historically, Mount Taishan was a place for emperors to hold worship ceremonies and where poets and writers came to seek inspiration. On Mount Taishan, visitors can enjoy stone inscriptions and temples, experiencing China's long history and rich culture."]}, {"id": "u3_s8_p4", "buf": ["The Tianshan Mountains stretch across the Xinjiang Uygur Autonomous Region and boast stunning snow-capped peaks, lush grasslands, and sparkling lakes. They are not only a magnificent natural landscape but also a place where diverse ethnic cultures meet. Historically, the Chang'an-Tianshan Corridor was a vital route along the Silk Road, facilitating the exchanges and integration of different ethnic groups and cultures. Today, visitors can experience diverse ethnic customs and explore impressive historical sites here."], "text": "The Tianshan Mountains stretch across the Xinjiang Uygur Autonomous Region and boast stunning snow-capped peaks, lush grasslands, and sparkling lakes. They are not only a magnificent natural landscape but also a place where diverse ethnic cultures meet. Historically, the Chang'an-Tianshan Corridor was a vital route along the Silk Road, facilitating the exchanges and integration of different ethnic groups and cultures. Today, visitors can experience diverse ethnic customs and explore impressive historical sites here.", "chunks": ["The Tianshan Mountains stretch across the Xinjiang Uygur Autonomous Region and boast stunning snow-capped peaks, lush grasslands, and sparkling lakes. They are not only a magnificent natural landscape but also a place where diverse ethnic cultures meet. Historically, the Chang'an-Tianshan Corridor was a vital route along the Silk Road, facilitating the exchanges and integration of different ethnic groups and cultures. Today, visitors can experience diverse ethnic customs and explore impressive historical sites here."]}, {"id": "u3_s8_p5", "buf": ["Jiuzhaigou Valley Scenic and Historic Interest Area, located in the Aba Tibetan and Qiang Autonomous Prefecture in Sichuan Province, is famous for its pristine and mysterious scenery. There are not only spectacular waterfalls, turquoise (青绿色的) lakes, and snow-capped mountains, but also abundant flora and fauna. The natural formation of Jiuzhaigou spans millions of years and is a spectacular example of nature's artistry. In Jiuzhaigou, visitors can truly feel the magic and power of nature."], "text": "Jiuzhaigou Valley Scenic and Historic Interest Area, located in the Aba Tibetan and Qiang Autonomous Prefecture in Sichuan Province, is famous for its pristine and mysterious scenery. There are not only spectacular waterfalls, turquoise (青绿色的) lakes, and snow-capped mountains, but also abundant flora and fauna. The natural formation of Jiuzhaigou spans millions of years and is a spectacular example of nature's artistry. In Jiuzhaigou, visitors can truly feel the magic and power of nature.", "chunks": ["Jiuzhaigou Valley Scenic and Historic Interest Area, located in the Aba Tibetan and Qiang Autonomous Prefecture in Sichuan Province, is famous for its pristine and mysterious scenery. There are not only spectacular waterfalls, turquoise (青绿色的) lakes, and snow-capped mountains, but also abundant flora and fauna. The natural formation of Jiuzhaigou spans millions of years and is a spectacular example of nature's artistry. In Jiuzhaigou, visitors can truly feel the magic and power of nature."]}, {"id": "u3_s8_p6", "buf": ["The Zhangjiajie National Forest Park is a famous scenic area in Hunan Province, boasting a unique landscape of towering rock peaks, clear streams, and lush forests. Its striking stone pillars, rising from the ground in various shapes, are often described as a natural museum of landforms. Zhangjiajie is not only a marvel of nature but also a region rich in cultural elements from the Tujia, Miao, and Bai ethnic groups. Visitors can marvel at the spectacular natural wonders of peaks, forests, canyons, and caves while learning about the traditional lifestyles and cultural practices of the local communities."], "text": "The Zhangjiajie National Forest Park is a famous scenic area in Hunan Province, boasting a unique landscape of towering rock peaks, clear streams, and lush forests. Its striking stone pillars, rising from the ground in various shapes, are often described as a natural museum of landforms. Zhangjiajie is not only a marvel of nature but also a region rich in cultural elements from the Tujia, Miao, and Bai ethnic groups. Visitors can marvel at the spectacular natural wonders of peaks, forests, canyons, and caves while learning about the traditional lifestyles and cultural practices of the local communities.", "chunks": ["The Zhangjiajie National Forest Park is a famous scenic area in Hunan Province, boasting a unique landscape of towering rock peaks, clear streams, and lush forests. Its striking stone pillars, rising from the ground in various shapes, are often described as a natural museum of landforms. Zhangjiajie is not only a marvel of nature but also a region rich in cultural elements from the Tujia, Miao, and Bai ethnic groups. Visitors can marvel at the spectacular natural wonders of peaks, forests, canyons, and caves while learning about the traditional lifestyles and cultural practices of the local communities."]}, {"id": "u3_s8_p7", "buf": ["The Sanjiangyuan area, located in the southern part of Qinghai Province, is the source of the Yangtze, Yellow, and Lancang rivers. As one of the most important ecological reserves in China, the area plays a critical role in maintaining China's ecological balance and water security. Historically, the Sanjiangyuan area has been home to several ethnic groups and has been considered one of the birthplaces of Chinese civilisation. In the Sanjiangyuan (Three-River-Source) National Park, visitors can feel the magical power of nature and the long history of human civilisation."], "text": "The Sanjiangyuan area, located in the southern part of Qinghai Province, is the source of the Yangtze, Yellow, and Lancang rivers. As one of the most important ecological reserves in China, the area plays a critical role in maintaining China's ecological balance and water security. Historically, the Sanjiangyuan area has been home to several ethnic groups and has been considered one of the birthplaces of Chinese civilisation. In the Sanjiangyuan (Three-River-Source) National Park, visitors can feel the magical power of nature and the long history of human civilisation.", "chunks": ["The Sanjiangyuan area, located in the southern part of Qinghai Province, is the source of the Yangtze, Yellow, and Lancang rivers. As one of the most important ecological reserves in China, the area plays a critical role in maintaining China's ecological balance and water security. Historically, the Sanjiangyuan area has been home to several ethnic groups and has been considered one of the birthplaces of Chinese civilisation. In the Sanjiangyuan (Three-River-Source) National Park, visitors can feel the magical power of nature and the long history of human civilisation."]}, {"id": "u3_s8_p8", "buf": ["The beauty and grandeur of China's natural landscapes attract countless domestic and international tourists. These sites are not only representative of natural splendour but also important carriers of Chinese history and culture. Whether travellers seek peace and relaxation or adventure and exploration, China's natural attractions offer unforgettable experiences and cherished memories."], "text": "The beauty and grandeur of China's natural landscapes attract countless domestic and international tourists. These sites are not only representative of natural splendour but also important carriers of Chinese history and culture. Whether travellers seek peace and relaxation or adventure and exploration, China's natural attractions offer unforgettable experiences and cherished memories.", "chunks": ["The beauty and grandeur of China's natural landscapes attract countless domestic and international tourists. These sites are not only representative of natural splendour but also important carriers of Chinese history and culture. Whether travellers seek peace and relaxation or adventure and exploration, China's natural attractions offer unforgettable experiences and cherished memories."]}]}]}, {"id": "u4", "title": "历史文化遗产", "sections": [{"id": "u4_s0", "title": "历史文化遗产", "paras": [{"id": "u4_s0_p1", "buf": ["China, with its long history and rich culture, prioritises the protection of its heritage through comprehensive policies. Investments in national, provincial, and grassroots museums have improved facilities, enriched exhibitions, and increased public engagement. National cultural parks (国家文化公园) and national archaeological site parks (国家考古遗址公园) also play a key role in heritage conservation. Meanwhile, red tourism, which focuses on revolutionary heritage, integrates historical resources with tourism to pass on the revolutionary spirit and boost local economies. These initiatives collectively preserve China's rich heritage and foster cultural pride."], "text": "China, with its long history and rich culture, prioritises the protection of its heritage through comprehensive policies. Investments in national, provincial, and grassroots museums have improved facilities, enriched exhibitions, and increased public engagement. National cultural parks (国家文化公园) and national archaeological site parks (国家考古遗址公园) also play a key role in heritage conservation. Meanwhile, red tourism, which focuses on revolutionary heritage, integrates historical resources with tourism to pass on the revolutionary spirit and boost local economies. These initiatives collectively preserve China's rich heritage and foster cultural pride.", "chunks": ["China, with its long history and rich culture, prioritises the protection of its heritage through comprehensive policies. Investments in national, provincial, and grassroots museums have improved facilities, enriched exhibitions, and increased public engagement. National cultural parks (国家文化公园) and national archaeological site parks (国家考古遗址公园) also play a key role in heritage conservation. Meanwhile, red tourism, which focuses on revolutionary heritage, integrates historical resources with tourism to pass on the revolutionary spirit and boost local economies. These initiatives collectively preserve China's rich heritage and foster cultural pride."]}]}, {"id": "u4_s1", "title": "历史文化博物馆", "paras": [{"id": "u4_s1_p1", "buf": ["China's national museums are treasures of the nation's long history and rich culture, offering profound insights into the nation's past, present, and future. These museums preserve invaluable cultural relics and serve as essential destinations for anyone exploring Chinese heritage."], "text": "China's national museums are treasures of the nation's long history and rich culture, offering profound insights into the nation's past, present, and future. These museums preserve invaluable cultural relics and serve as essential destinations for anyone exploring Chinese heritage.", "chunks": ["China's national museums are treasures of the nation's long history and rich culture, offering profound insights into the nation's past, present, and future. These museums preserve invaluable cultural relics and serve as essential destinations for anyone exploring Chinese heritage."]}, {"id": "u4_s1_p2", "buf": ["The National Museum of China is the largest comprehensive national museum in the country. It houses precious relics from ancient times to the modern era, including exquisite porcelain, spectacular Buddhist sculptures, and unique costumes. Visitors can appreciate artefacts such as Shang- and Zhou-dynasty bronzes, Han Dynasty jades, and Tang Dynasty silk textiles, all of which showcase the splendour of China's civilisation."], "text": "The National Museum of China is the largest comprehensive national museum in the country. It houses precious relics from ancient times to the modern era, including exquisite porcelain, spectacular Buddhist sculptures, and unique costumes. Visitors can appreciate artefacts such as Shang- and Zhou-dynasty bronzes, Han Dynasty jades, and Tang Dynasty silk textiles, all of which showcase the splendour of China's civilisation.", "chunks": ["The National Museum of China is the largest comprehensive national museum in the country. It houses precious relics from ancient times to the modern era, including exquisite porcelain, spectacular Buddhist sculptures, and unique costumes. Visitors can appreciate artefacts such as Shang- and Zhou-dynasty bronzes, Han Dynasty jades, and Tang Dynasty silk textiles, all of which showcase the splendour of China's civilisation."]}, {"id": "u4_s1_p3", "buf": ["In addition to the National Museum of China, there are cultural and historical museums at the provincial, municipal, and county levels across the country. Visiting these museums, people can gain a deeper understanding of the local history and culture and better appreciate China's treasures. For instance, the Shaanxi History Museum is a place visitors cannot miss. It houses a large collection of precious relics ranging from prehistoric times to modern times, with artefacts from the Han and Tang dynasties being the most representative. Visitors can admire pottery figurines from the Han Dynasty, murals and porcelains from the Tang Dynasty, and other treasures that reveal the unique charm of ancient Chinese culture."], "text": "In addition to the National Museum of China, there are cultural and historical museums at the provincial, municipal, and county levels across the country. Visiting these museums, people can gain a deeper understanding of the local history and culture and better appreciate China's treasures. For instance, the Shaanxi History Museum is a place visitors cannot miss. It houses a large collection of precious relics ranging from prehistoric times to modern times, with artefacts from the Han and Tang dynasties being the most representative. Visitors can admire pottery figurines from the Han Dynasty, murals and porcelains from the Tang Dynasty, and other treasures that reveal the unique charm of ancient Chinese culture.", "chunks": ["In addition to the National Museum of China, there are cultural and historical museums at the provincial, municipal, and county levels across the country. Visiting these museums, people can gain a deeper understanding of the local history and culture and better appreciate China's treasures. For instance, the Shaanxi History Museum is a place visitors cannot miss. It houses a large collection of precious relics ranging from prehistoric times to modern times, with artefacts from the Han and Tang dynasties being the most representative. Visitors can admire pottery figurines from the Han Dynasty, murals and porcelains from the Tang Dynasty, and other treasures that reveal the unique charm of ancient Chinese culture."]}]}, {"id": "u4_s2", "title": "国家文化公园与国家考古遗址公园", "paras": [{"id": "u4_s2_p1", "buf": ["China's national cultural parks and archaeological site parks are important carriers of the nation's history and culture, attracting numerous visitors with their unique landscapes and rich cultural significance. These parks are not only treasure troves of China's cultural heritage but also vital windows showcasing the country's civilisation and culture to the world."], "text": "China's national cultural parks and archaeological site parks are important carriers of the nation's history and culture, attracting numerous visitors with their unique landscapes and rich cultural significance. These parks are not only treasure troves of China's cultural heritage but also vital windows showcasing the country's civilisation and culture to the world.", "chunks": ["China's national cultural parks and archaeological site parks are important carriers of the nation's history and culture, attracting numerous visitors with their unique landscapes and rich cultural significance. These parks are not only treasure troves of China's cultural heritage but also vital windows showcasing the country's civilisation and culture to the world."]}]}, {"id": "u4_s3", "title": "国家文化公园", "paras": [{"id": "u4_s3_p1", "buf": ["China's national cultural parks include the Great Wall National Cultural Park, the Grand Canal National Cultural Park, the Long March National Cultural Park, the Yellow River National Cultural Park, and the Yangtze River National Cultural Park. Each of these parks represents the cultural characteristics and national spirit of China from different perspectives. The establishment of these parks not only helps to protect and pass on important cultural heritage but also enables more people to understand and appreciate China's history and culture."], "text": "China's national cultural parks include the Great Wall National Cultural Park, the Grand Canal National Cultural Park, the Long March National Cultural Park, the Yellow River National Cultural Park, and the Yangtze River National Cultural Park. Each of these parks represents the cultural characteristics and national spirit of China from different perspectives. The establishment of these parks not only helps to protect and pass on important cultural heritage but also enables more people to understand and appreciate China's history and culture.", "chunks": ["China's national cultural parks include the Great Wall National Cultural Park, the Grand Canal National Cultural Park, the Long March National Cultural Park, the Yellow River National Cultural Park, and the Yangtze River National Cultural Park. Each of these parks represents the cultural characteristics and national spirit of China from different perspectives. The establishment of these parks not only helps to protect and pass on important cultural heritage but also enables more people to understand and appreciate China's history and culture."]}, {"id": "u4_s3_p2", "buf": ["The Great Wall National Cultural Park embodies China's ancient military defence system and showcases the resilience, unity, and ingenuity of the Chinese people. Meanwhile, the Grand Canal National Cultural Park highlights the achievements of ancient water conservancy and promotes understanding of China's historical trade and cultural exchanges. The Long March National Cultural Park serves as a red education base, commemorating the perseverance and sacrifice of the Red Army. The Yellow River and the Yangtze River national cultural parks present the ecological landscapes and cultural richness of the two mother rivers of the Chinese nation, raising public awareness of various regional histories and environmental legacies."], "text": "The Great Wall National Cultural Park embodies China's ancient military defence system and showcases the resilience, unity, and ingenuity of the Chinese people. Meanwhile, the Grand Canal National Cultural Park highlights the achievements of ancient water conservancy and promotes understanding of China's historical trade and cultural exchanges. The Long March National Cultural Park serves as a red education base, commemorating the perseverance and sacrifice of the Red Army. The Yellow River and the Yangtze River national cultural parks present the ecological landscapes and cultural richness of the two mother rivers of the Chinese nation, raising public awareness of various regional histories and environmental legacies.", "chunks": ["The Great Wall National Cultural Park embodies China's ancient military defence system and showcases the resilience, unity, and ingenuity of the Chinese people. Meanwhile, the Grand Canal National Cultural Park highlights the achievements of ancient water conservancy and promotes understanding of China's historical trade and cultural exchanges. The Long March National Cultural Park serves as a red education base, commemorating the perseverance and sacrifice of the Red Army. The Yellow River and the Yangtze River national cultural parks present the ecological landscapes and cultural richness of the two mother rivers of the Chinese nation, raising public awareness of various regional histories and environmental legacies."]}]}, {"id": "u4_s4", "title": "国家考古遗址公园", "paras": [{"id": "u4_s4_p1", "buf": ["National archaeological site parks are important places for protecting and presenting archaeological sites, such as the Yinxu National Archaeological Site Park in Henan Province, the Emperor Qin Shihuang's Mausoleum National Archaeological Site Park in Shaanxi Province, the Tomb of the Marquis of Haihun in Jiangxi Province, and the Archaeological Ruins of Liangzhu City in Zhejiang Province. Combining archaeological sites with natural landscapes through scientific planning and meticulous protection, these sites are all precious legacies of ancient Chinese civilisation."], "text": "National archaeological site parks are important places for protecting and presenting archaeological sites, such as the Yinxu National Archaeological Site Park in Henan Province, the Emperor Qin Shihuang's Mausoleum National Archaeological Site Park in Shaanxi Province, the Tomb of the Marquis of Haihun in Jiangxi Province, and the Archaeological Ruins of Liangzhu City in Zhejiang Province. Combining archaeological sites with natural landscapes through scientific planning and meticulous protection, these sites are all precious legacies of ancient Chinese civilisation.", "chunks": ["National archaeological site parks are important places for protecting and presenting archaeological sites, such as the Yinxu National Archaeological Site Park in Henan Province, the Emperor Qin Shihuang's Mausoleum National Archaeological Site Park in Shaanxi Province, the Tomb of the Marquis of Haihun in Jiangxi Province, and the Archaeological Ruins of Liangzhu City in Zhejiang Province. Combining archaeological sites with natural landscapes through scientific planning and meticulous protection, these sites are all precious legacies of ancient Chinese civilisation."]}, {"id": "u4_s4_p2", "buf": ["By integrating archaeological findings with their surrounding landscapes, these parks provide a valuable opportunity to explore China's dynastic past, from the bronze culture of the Shang Dynasty to the imperial grandeur of the Qin Dynasty, and the aristocratic lifestyle of the Western Han Dynasty. Together, these parks reflect China's continuous efforts to protect cultural relics while enhancing public access to and appreciation of its historical legacy."], "text": "By integrating archaeological findings with their surrounding landscapes, these parks provide a valuable opportunity to explore China's dynastic past, from the bronze culture of the Shang Dynasty to the imperial grandeur of the Qin Dynasty, and the aristocratic lifestyle of the Western Han Dynasty. Together, these parks reflect China's continuous efforts to protect cultural relics while enhancing public access to and appreciation of its historical legacy.", "chunks": ["By integrating archaeological findings with their surrounding landscapes, these parks provide a valuable opportunity to explore China's dynastic past, from the bronze culture of the Shang Dynasty to the imperial grandeur of the Qin Dynasty, and the aristocratic lifestyle of the Western Han Dynasty. Together, these parks reflect China's continuous efforts to protect cultural relics while enhancing public access to and appreciation of its historical legacy."]}]}, {"id": "u4_s5", "title": "红色旅游景点", "paras": [{"id": "u4_s5_p1", "buf": ["China's red tourism has its roots in the country's revolutionary history under the leadership of the Communist Party of China. It serves as an important avenue for patriotic education and plays a key role in preserving and transmitting the revolutionary spirit. Through the commemoration of major historical events and figures, red tourism showcases China's modern historical development and promotes awareness of its political and cultural heritage."], "text": "China's red tourism has its roots in the country's revolutionary history under the leadership of the Communist Party of China. It serves as an important avenue for patriotic education and plays a key role in preserving and transmitting the revolutionary spirit. Through the commemoration of major historical events and figures, red tourism showcases China's modern historical development and promotes awareness of its political and cultural heritage.", "chunks": ["China's red tourism has its roots in the country's revolutionary history under the leadership of the Communist Party of China. It serves as an important avenue for patriotic education and plays a key role in preserving and transmitting the revolutionary spirit. Through the commemoration of major historical events and figures, red tourism showcases China's modern historical development and promotes awareness of its political and cultural heritage."]}, {"id": "u4_s5_p2", "buf": ["China's red tourist attractions are widely distributed across various provinces and regions, including Beijing, Shanghai, Hunan, Jiangxi, and Shaanxi. These sites feature revolutionary landmarks, memorial halls, martyrs' cemeteries, and other places that bear witness to significant events and figures in China's revolutionary history. Among them, the Yan'an Revolutionary Heritage Site includes the Zaoyuan Revolutionary Site, the Yangjialing Revolutionary Site, the Site of the CCCPC Northwest Bureau (中共中央西北局旧址), and the Yan'an Revolutionary Memorial Hall. This scenic area is a representative example among the 445 revolutionary relics found in Yan'an. It has been designated as a major national education base for patriotism, revolutionary tradition, and the \"Yan'an spirit\"."], "text": "China's red tourist attractions are widely distributed across various provinces and regions, including Beijing, Shanghai, Hunan, Jiangxi, and Shaanxi. These sites feature revolutionary landmarks, memorial halls, martyrs' cemeteries, and other places that bear witness to significant events and figures in China's revolutionary history. Among them, the Yan'an Revolutionary Heritage Site includes the Zaoyuan Revolutionary Site, the Yangjialing Revolutionary Site, the Site of the CCCPC Northwest Bureau (中共中央西北局旧址), and the Yan'an Revolutionary Memorial Hall. This scenic area is a representative example among the 445 revolutionary relics found in Yan'an. It has been designated as a major national education base for patriotism, revolutionary tradition, and the \"Yan'an spirit\".", "chunks": ["China's red tourist attractions are widely distributed across various provinces and regions, including Beijing, Shanghai, Hunan, Jiangxi, and Shaanxi. These sites feature revolutionary landmarks, memorial halls, martyrs' cemeteries, and other places that bear witness to significant events and figures in China's revolutionary history. Among them, the Yan'an Revolutionary Heritage Site includes the Zaoyuan Revolutionary Site, the Yangjialing Revolutionary Site, the Site of the CCCPC Northwest Bureau (中共中央西北局旧址), and the Yan'an Revolutionary Memorial Hall. This scenic area is a representative example among the 445 revolutionary relics found in Yan'an. It has been designated as a major national education base for patriotism, revolutionary tradition, and the \"Yan'an spirit\"."]}, {"id": "u4_s5_p3", "buf": ["The Jinggang Mountains Scenic Area in Jiangxi Province is another renowned red tourism destination. The Jinggang Mountains, nestled in the Luoxiao Mountains (罗霄山脉) near the border between Jiangxi and Hunan provinces, are known as the cradle of the Chinese revolution. Other popular red tourism sites include the Museum of the War of the Chinese People's Resistance Against Japanese Aggression, the Zunyi Conference Memorial Museum, and the Museum of the Wuchang Uprising of the Revolution of 1911."], "text": "The Jinggang Mountains Scenic Area in Jiangxi Province is another renowned red tourism destination. The Jinggang Mountains, nestled in the Luoxiao Mountains (罗霄山脉) near the border between Jiangxi and Hunan provinces, are known as the cradle of the Chinese revolution. Other popular red tourism sites include the Museum of the War of the Chinese People's Resistance Against Japanese Aggression, the Zunyi Conference Memorial Museum, and the Museum of the Wuchang Uprising of the Revolution of 1911.", "chunks": ["The Jinggang Mountains Scenic Area in Jiangxi Province is another renowned red tourism destination. The Jinggang Mountains, nestled in the Luoxiao Mountains (罗霄山脉) near the border between Jiangxi and Hunan provinces, are known as the cradle of the Chinese revolution. Other popular red tourism sites include the Museum of the War of the Chinese People's Resistance Against Japanese Aggression, the Zunyi Conference Memorial Museum, and the Museum of the Wuchang Uprising of the Revolution of 1911."]}, {"id": "u4_s5_p4", "buf": ["Red tourism has become an integral part of China's tourism industry, contributing to local economic development and enhancing public understanding of the nation's history. By visiting these sites, tourists can explore China's revolutionary past, understand its journey towards modernisation, and recognise its cultural achievements. These attractions also serve as platforms for cultural exchanges, strengthening connections and friendships between China and the world."], "text": "Red tourism has become an integral part of China's tourism industry, contributing to local economic development and enhancing public understanding of the nation's history. By visiting these sites, tourists can explore China's revolutionary past, understand its journey towards modernisation, and recognise its cultural achievements. These attractions also serve as platforms for cultural exchanges, strengthening connections and friendships between China and the world.", "chunks": ["Red tourism has become an integral part of China's tourism industry, contributing to local economic development and enhancing public understanding of the nation's history. By visiting these sites, tourists can explore China's revolutionary past, understand its journey towards modernisation, and recognise its cultural achievements. These attractions also serve as platforms for cultural exchanges, strengthening connections and friendships between China and the world."]}]}]}], "vocabA": [{"term": "leisure and entertainment", "zh": "休闲娱乐", "q": "Leisure and entertainment have become an essential part of Chinese people's daily lives. People are increasingly drawn to cultural activities for spiritual enrichment, especially as they enjoy more fr", "tr": "休闲娱乐已成为中国人日常生活中不可缺少的一部分。随着人们拥有更多的闲暇时间和更高的收入，越来越多的人为了求得精神的充实而投身文化活动。参观博物馆、美术馆和文化中心，以及去听音乐会、看戏、看电影，已成为热门的休闲方式。", "pos": "术语", "src": "原文"}, {"term": "cultural leisure activities", "zh": "文化休闲活动", "q": "Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to t", "tr": "文化休闲活动并不局限于城市。在农村地区，庙会、地方戏曲演出、踩高跷表演、民间说书等传统活动依然兴盛。文化惠民工程的启动和乡村文化振兴的推进，为农村社区带来了更多的文化演出和活动，丰富了居民的生活。在许多农村地区，演出在文化广场和农家院落中举行，深受当地村民喜爱。“村晚”近年来极受欢迎。2023年，全国举办了2万多场“村晚”，参与者约1.3亿人次。", "pos": "术语", "src": "原文"}, {"term": "National Museum of China", "zh": "中国国家博物馆", "q": "China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally ", "tr": "中国的文化基础设施显著扩展。例如，截至2024年底，全国博物馆总数已超过7000座，数量位居世界前列。为了吸引和留住参观者，许多博物馆在展览中运用了创新技术。例如，2023年，北京的中国国家博物馆举办了名为“壮丽辉煌：石窟艺术沉浸式体验”的展览，运用人工智能和数字成像等技术，重现了莫高窟、龙门石窟等文化瑰宝。", "pos": "机构", "src": "原文"}, {"term": "Mogao Grottoes", "zh": "莫高窟", "q": "China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally ", "tr": "中国的文化基础设施显著扩展。例如，截至2024年底，全国博物馆总数已超过7000座，数量位居世界前列。为了吸引和留住参观者，许多博物馆在展览中运用了创新技术。例如，2023年，北京的中国国家博物馆举办了名为“壮丽辉煌：石窟艺术沉浸式体验”的展览，运用人工智能和数字成像等技术，重现了莫高窟、龙门石窟等文化瑰宝。", "pos": "建筑", "src": "原文"}, {"term": "Longmen Grottoes", "zh": "龙门石窟", "q": "China has witnessed a significant expansion of its cultural infrastructure. For instance, by the end of 2024, the total number of museums nationwide had exceeded 7,000, ranking among the top globally ", "tr": "中国的文化基础设施显著扩展。例如，截至2024年底，全国博物馆总数已超过7000座，数量位居世界前列。为了吸引和留住参观者，许多博物馆在展览中运用了创新技术。例如，2023年，北京的中国国家博物馆举办了名为“壮丽辉煌：石窟艺术沉浸式体验”的展览，运用人工智能和数字成像等技术，重现了莫高窟、龙门石窟等文化瑰宝。", "pos": "建筑", "src": "原文"}, {"term": "National Centre for the Performing Arts", "zh": "国家大剧院", "q": "China's cultural scene is remarkably rich and diverse, providing abundant opportunities for artistic enjoyment. For example, the National Centre for the Performing Arts (国家大剧院), a renowned performing ", "tr": "中国的文化图景极为丰富多样，为艺术欣赏提供了大量机会。例如，国家大剧院是一处著名的表演艺术场所，常年上演由世界各地知名艺术家带来的音乐会、歌剧和戏剧演出。自2007年以来，这座艺术中心已上演和委约创作了100多部作品，涵盖歌剧、话剧、京剧和舞剧。", "pos": "机构", "src": "原文"}, {"term": "Beijing's 798 Art District", "zh": "北京798艺术区", "q": "New cultural venues such as creative bazaars, handicraft exhibitions, and cultural and creative industry parks also provide opportunities for people to engage with arts. For example, Shanghai's Tianzi", "tr": "创意集市、手工艺展览、文化创意产业园等新型文化场所，也为人们接触艺术提供了机会。例如，上海的田子坊是一个国际文化创意产业园区，聚集了近400家店铺，包括画廊、工作室、手工艺店、时尚精品店、餐厅和咖啡馆。游客可以欣赏各种独特的艺术品，购买手工艺品，并参加各类创意工坊和艺术讲座。同样，北京的798艺术区吸引着无数艺术家和游客，将昔日的工业场地转变为充满活力的文化中心。", "pos": "其他", "src": "原文"}, {"term": "public-interest cultural programmes", "zh": "文化惠民工程", "q": "Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to t", "tr": "文化休闲活动并不局限于城市。在农村地区，庙会、地方戏曲演出、踩高跷表演、民间说书等传统活动依然兴盛。文化惠民工程的启动和乡村文化振兴的推进，为农村社区带来了更多的文化演出和活动，丰富了居民的生活。在许多农村地区，演出在文化广场和农家院落中举行，深受当地村民喜爱。“村晚”近年来极受欢迎。2023年，全国举办了2万多场“村晚”，参与者约1.3亿人次。", "pos": "其他", "src": "原文"}, {"term": "village spring festival gala", "zh": "村晚", "q": "Cultural leisure activities extend beyond urban settings. In rural areas, traditional events such as temple fairs, local opera performances, stilt walking displays, and folk storytelling continue to t", "tr": "文化休闲活动并不局限于城市。在农村地区，庙会、地方戏曲演出、踩高跷表演、民间说书等传统活动依然兴盛。文化惠民工程的启动和乡村文化振兴的推进，为农村社区带来了更多的文化演出和活动，丰富了居民的生活。在许多农村地区，演出在文化广场和农家院落中举行，深受当地村民喜爱。“村晚”近年来极受欢迎。2023年，全国举办了2万多场“村晚”，参与者约1.3亿人次。", "pos": "其他", "src": "原文"}, {"term": "sports-related leisure activities", "zh": "体育休闲活动", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "village super league", "zh": "村超", "q": "The \"village super league (村超)\", a non-professional football league held in Rongjiang County, Guizhou Province, has become a hot topic and gained massive popularity across China. More than just a foot", "tr": "“村超”是贵州省榕江县举办的一项非职业足球联赛，已成为热门话题，风靡全国。它不仅仅是一场足球比赛，更成为一个展示中国乡村活力与文化魅力的生动平台。它的魅力在于接地气的风格、喜庆的氛围和丰富的民族元素。此外，球员们精湛的球技、充满激情的表现，以及观众极具感染力的热情，也为其增色不少。", "pos": "其他", "src": "原文"}, {"term": "digital entertainment", "zh": "数字娱乐", "q": "China has been transforming into a digitally connected society. Digital entertainment has become an important part of modern life, offering new and diverse forms of leisure experiences in the virtual ", "tr": "中国正转变为一个数字化互联的社会。数字娱乐已成为现代生活的重要组成部分，在虚拟世界中为人们提供新颖而多样的休闲体验。各类网络平台让人们得以与朋友联络、分享生活点滴、浏览新闻，并参与在线讨论。", "pos": "术语", "src": "原文"}, {"term": "smart tourism", "zh": "智慧旅游", "q": "In recent years, digital technology has revolutionised leisure and cultural experiences in China. From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions", "tr": "近年来，数字技术彻底改变了中国的休闲和文化体验。从在线聊天、观看直播、网上购物，到参观虚拟博物馆展览、体验智慧旅游，数字娱乐已成为现代生活中不可或缺的一部分。这些新颖的线上休闲形式不仅重塑了人们的娱乐方式，也满足了人们在快速演变的数字环境中多样化的需求。", "pos": "术语", "src": "原文"}, {"term": "online shopping", "zh": "网上购物", "q": "In China, online shopping has become an important part of daily life. By connecting the physical world with the virtual one, online shopping saves people time and energy. According to the 56th Statist", "tr": "在中国，网上购物已成为日常生活的重要组成部分。网上购物将现实世界与虚拟世界连接起来，为人们节省了时间和精力。根据中国互联网络信息中心2025年7月发布的第56次《中国互联网络发展状况统计报告》，截至2025年6月，中国网民规模已超过11.2亿，互联网普及率达79.7%。其中，网上购物平台用户约9.8亿，占网民总数的86.9%。与此同时，直播购物的流行使互动式的网上购物成为一种新的数字娱乐形式。", "pos": "术语", "src": "原文"}, {"term": "virtual museum exhibitions", "zh": "虚拟博物馆展览", "q": "In recent years, digital technology has revolutionised leisure and cultural experiences in China. From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions", "tr": "近年来，数字技术彻底改变了中国的休闲和文化体验。从在线聊天、观看直播、网上购物，到参观虚拟博物馆展览、体验智慧旅游，数字娱乐已成为现代生活中不可或缺的一部分。这些新颖的线上休闲形式不仅重塑了人们的娱乐方式，也满足了人们在快速演变的数字环境中多样化的需求。", "pos": "术语", "src": "原文"}, {"term": "Visitors Appreciating the Animated Along the River During the Qingming Festival", "zh": "观众欣赏动态版《清明上河图》", "q": "", "tr": "", "pos": "其他", "src": "原文"}, {"term": "the Panoramic Palace Museum", "zh": "全景故宫", "q": "The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Mus", "tr": "故宫博物院推出了多款线上游览应用，包括“全景故宫”“数字文物库”“数字多宝阁”和“故宫展览”。借助这些工具，公众足不出户便能游览故宫博物院、探索其馆藏。即便线下展览结束，用户仍可通过官方网站或博物院的应用继续观展。", "pos": "其他", "src": "原文"}, {"term": "Digital Cultural Relic Library", "zh": "数字文物库", "q": "The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Mus", "tr": "故宫博物院推出了多款线上游览应用，包括“全景故宫”“数字文物库”“数字多宝阁”和“故宫展览”。借助这些工具，公众足不出户便能游览故宫博物院、探索其馆藏。即便线下展览结束，用户仍可通过官方网站或博物院的应用继续观展。", "pos": "其他", "src": "原文"}, {"term": "Digital Treasure Hall", "zh": "数字多宝阁", "q": "The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Mus", "tr": "故宫博物院推出了多款线上游览应用，包括“全景故宫”“数字文物库”“数字多宝阁”和“故宫展览”。借助这些工具，公众足不出户便能游览故宫博物院、探索其馆藏。即便线下展览结束，用户仍可通过官方网站或博物院的应用继续观展。", "pos": "其他", "src": "原文"}, {"term": "The Ferryman of Ink World", "zh": "丹青宝筏", "q": "The Shanghai Museum has also embraced digital technology in its exhibition The Ferryman of Ink World (丹青宝筏): Dong Qichang's Calligraphy and Painting Art. By integrating virtual elements into the displ", "tr": "上海博物馆在其展览“丹青宝筏：董其昌书画艺术”中也运用了数字技术。通过将虚拟元素融入展陈，博物馆既提升了学术阐释，也增强了观众的参与感。数字时间轴、虚拟地图等互动功能，让观众得以了解董其昌的生平、艺术发展和游历经历，体现了该博物馆将传统艺术研究与数字人文实践相结合的创新做法。", "pos": "其他", "src": "原文"}, {"term": "the Potala Palace", "zh": "布达拉宫", "q": "At the same time, major internet platforms in China launched livestreamed museum tours, with dozens of cultural institutions across the country taking part. The Potala Palace (布达拉宫) had its first live", "tr": "与此同时，中国各大互联网平台推出了博物馆直播游览，全国数十家文化机构参与其中。布达拉宫于2020年首次进行网络直播，带领近百万观众走进通常不对外开放的区域。在一个小时的时间里，观众可以看到其古籍数字化工作现场以及金顶殿堂。西安碑林博物馆的一场直播吸引了约40万观众。故宫博物院在多个网络平台上直播春日景致，展示了开馆前后博物馆的美景，仅在单一平台上就吸引了近千万观众。", "pos": "建筑", "src": "原文"}, {"term": "tourism resources and attractions", "zh": "旅游资源与景点", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "major tourist cities", "zh": "主要旅游城市", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "Monument to the People's Heroes", "zh": "人民英雄纪念碑", "q": "Tian'anmen Square attracts tens of thousands of visitors each day. The imposing Tian'anmen Gate stands at its northern end. The five-star red flag flies high above, and the Monument to the People's He", "tr": "天安门广场每天都吸引着成千上万的游客。雄伟的天安门城楼矗立在广场北端。五星红旗高高飘扬，人民英雄纪念碑位于广场中央。广场西侧是人民大会堂，东侧是中国国家博物馆。", "pos": "建筑", "src": "原文"}, {"term": "Great Hall of the People", "zh": "人民大会堂", "q": "Tian'anmen Square attracts tens of thousands of visitors each day. The imposing Tian'anmen Gate stands at its northern end. The five-star red flag flies high above, and the Monument to the People's He", "tr": "天安门广场每天都吸引着成千上万的游客。雄伟的天安门城楼矗立在广场北端。五星红旗高高飘扬，人民英雄纪念碑位于广场中央。广场西侧是人民大会堂，东侧是中国国家博物馆。", "pos": "机构", "src": "原文"}, {"term": "acoustics", "zh": "声学", "q": "The Temple of Heaven, a masterpiece of architecture and landscape design, is situated in southern Beijing. It was once the place where emperors of the Ming and Qing dynasties worshipped Heaven and pra", "tr": "天坛是建筑与景观设计的杰作，位于北京南部。它曾是明清两代皇帝祭天祈谷的场所。天坛具有象征意义的布局和设计，体现了中国古代建筑的智慧与巧思。建筑群由两道墙垣围合。南侧墙垣的转角都是直角，而北侧的转角则呈圆弧形，这反映了中国古代“天圆地方”的观念。北侧墙垣地势更高，象征着天高于地。两道围墙将天坛分为内坛和外坛。如今，天坛是一座文化博物馆，展示着帝王祭天的礼仪，将建筑、美学、声学、天文、历法、音乐和舞蹈融为一体，和谐统一。它是了解中国历史的一扇重要窗口。", "pos": "术语", "src": "原文"}, {"term": "Longevity Hill", "zh": "万寿山", "q": "The Summer Palace lies in the northwest of Beijing. Covering an area of approximately 300 hectares, it is one of the largest imperial gardens in the world. The Summer Palace features the Longevity Hil", "tr": "颐和园位于北京西北部，占地约300公顷，是世界上最大的皇家园林之一。园内有万寿山和昆明湖，还拥有3000多座古建筑，包括亭、桥、廊、殿、堂等，堪称中国古典园林建筑的一座博物馆。", "pos": "其他", "src": "原文"}, {"term": "the Bund", "zh": "外滩", "q": "Home to famous landmarks such as the Bund (外滩) and Nanjing Road, Shanghai is one of China's most international metropolises, attracting substantial foreign investment and numerous tourists. Since the ", "tr": "上海拥有外滩、南京路等著名地标，是中国最国际化的都市之一，吸引着大量外资和众多游客。自20世纪90年代以来，上海加强了在科技创新、金融和文化发展方面的引领作用，建立了陆家嘴金融贸易区、张江高科技园区等多个功能区。", "pos": "其他", "src": "原文"}, {"term": "The Scenic Spot of Three Pools Mirroring the Moon in West Lake", "zh": "西湖三潭映月", "q": "", "tr": "", "pos": "其他", "src": "原文"}, {"term": "Six Harmonies Pagoda", "zh": "六和塔", "q": "Hangzhou is renowned for its surrounding hills and beautiful scenery, especially the West Lake. Other popular tourist attractions include the Six Harmonies Pagoda (六和塔) and the Lingyin Temple. Hangzho", "tr": "杭州以周边的群山和秀丽的风景而闻名，尤其是西湖。其他热门旅游景点还包括六和塔和灵隐寺。杭州还以中国主要的丝绸产区之一著称。此外，这座城市还以其龙井茶闻名，龙井茶香气清爽、滋味醇厚、叶形美观、色泽翠绿。", "pos": "建筑", "src": "原文"}, {"term": "the Great Mosque", "zh": "大清真寺", "q": "Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its ", "tr": "西安是陕西省省会，在包括西周、秦、西汉、隋、唐在内的13个朝代中，作为中国的都城长达一千多年。这座城市及其周边地区常被誉为中国的“自然与历史博物馆”。西安拥有多处宏大的帝王宫殿遗址，如秦朝的阿房宫、汉代的未央宫，以及唐朝的大明宫和华清宫。城中还有许多其他历史遗迹，包括大清真寺、大雁塔、小雁塔以及钟鼓楼。这一地区还集中分布着秦、汉、唐三代的帝王陵墓，其中最著名的是秦始皇陵，这一广袤的陵区包括举世闻名的兵马俑——常被称作“世界第八大奇迹”。", "pos": "建筑", "src": "原文"}, {"term": "Big Wild Goose Pagoda", "zh": "大雁塔", "q": "Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its ", "tr": "西安是陕西省省会，在包括西周、秦、西汉、隋、唐在内的13个朝代中，作为中国的都城长达一千多年。这座城市及其周边地区常被誉为中国的“自然与历史博物馆”。西安拥有多处宏大的帝王宫殿遗址，如秦朝的阿房宫、汉代的未央宫，以及唐朝的大明宫和华清宫。城中还有许多其他历史遗迹，包括大清真寺、大雁塔、小雁塔以及钟鼓楼。这一地区还集中分布着秦、汉、唐三代的帝王陵墓，其中最著名的是秦始皇陵，这一广袤的陵区包括举世闻名的兵马俑——常被称作“世界第八大奇迹”。", "pos": "建筑", "src": "原文"}, {"term": "Small Wild Goose Pagoda", "zh": "小雁塔", "q": "Xi'an, the capital of Shaanxi Province, served as China's capital for more than 1,000 years under 13 dynasties, including the Western Zhou, Qin, Western Han, Sui, and Tang dynasties. The city and its ", "tr": "西安是陕西省省会，在包括西周、秦、西汉、隋、唐在内的13个朝代中，作为中国的都城长达一千多年。这座城市及其周边地区常被誉为中国的“自然与历史博物馆”。西安拥有多处宏大的帝王宫殿遗址，如秦朝的阿房宫、汉代的未央宫，以及唐朝的大明宫和华清宫。城中还有许多其他历史遗迹，包括大清真寺、大雁塔、小雁塔以及钟鼓楼。这一地区还集中分布着秦、汉、唐三代的帝王陵墓，其中最著名的是秦始皇陵，这一广袤的陵区包括举世闻名的兵马俑——常被称作“世界第八大奇迹”。", "pos": "建筑", "src": "原文"}, {"term": "serving the dead as one serves the living", "zh": "事死如事生", "q": "Following the traditional belief of \"serving the dead as one serves the living (事死如事生)\", Emperor Qin Shihuang recreated the luxury and splendour of his lifetime within his tomb, commissioning a magnif", "tr": "遵循“事死如事生”的传统观念，秦始皇在自己的陵墓中再现了生前的奢华与辉煌，为自己营建了一座宏伟的帝王陵寝。他深知武力的重要性，下令制作与真人等大的陶俑陪葬于陵墓附近，以护卫自己的灵魂。兵马俑由此形成。", "pos": "术语", "src": "原文"}, {"term": "prayer wheels", "zh": "转经筒", "q": "Lhasa, the capital of the Xizang Autonomous Region, is one of the highest cities in the world, with an elevation of approximately 3,650 metres. Its recorded history dates back about 1,300 years. Locat", "tr": "拉萨是西藏自治区的首府，也是世界上海拔最高的城市之一，海拔约3650米。其有记载的历史可追溯至约1300年前。拉萨坐落于群山环抱的盆地之中，风景令人叹为观止，精神氛围也别具一格。这座城市将传统生活与现代生活融为一体，转经筒与闪亮的街灯并立，构成一幅令游客过目难忘的景象。", "pos": "其他", "src": "原文"}, {"term": "Princess Wencheng", "zh": "文成公主", "q": "The Potala Palace is located on the Red Hill, in the northwest of Lhasa. It was originally built in the seventh century during the reign of Songtsen Gampo (松赞干布), who established the Tubo Kingdom (吐蕃王", "tr": "布达拉宫位于拉萨西北部的红山上。它最初建于7世纪，当时松赞干布在位，他在今天的西藏地区建立了吐蕃王国，并定都拉萨。唐朝皇帝派遣文成公主与松赞干布联姻。为迎娶公主，松赞干布修建了布达拉宫。布达拉宫后来在战乱和自然灾害中被毁，并于17世纪重建。现在的布达拉宫高约115米，共13层。整座建筑由石材和木材建成，墙体平均厚达3米。宫内收藏着大量雕塑、壁画、经书等珍贵文物。", "pos": "其他", "src": "原文"}, {"term": "the Tubo Kingdom", "zh": "吐蕃王国", "q": "The Potala Palace is located on the Red Hill, in the northwest of Lhasa. It was originally built in the seventh century during the reign of Songtsen Gampo (松赞干布), who established the Tubo Kingdom (吐蕃王", "tr": "布达拉宫位于拉萨西北部的红山上。它最初建于7世纪，当时松赞干布在位，他在今天的西藏地区建立了吐蕃王国，并定都拉萨。唐朝皇帝派遣文成公主与松赞干布联姻。为迎娶公主，松赞干布修建了布达拉宫。布达拉宫后来在战乱和自然灾害中被毁，并于17世纪重建。现在的布达拉宫高约115米，共13层。整座建筑由石材和木材建成，墙体平均厚达3米。宫内收藏着大量雕塑、壁画、经书等珍贵文物。", "pos": "其他", "src": "原文"}, {"term": "natural attractions", "zh": "自然景观", "q": "3 What are some iconic natural attractions in China that you think best represent the country's landscape?", "tr": "3 你认为中国有哪些标志性的自然景观最能代表这个国家的山水风光？", "pos": "术语", "src": "原文"}, {"term": "peculiar pines", "zh": "奇松", "q": "Mount Huangshan, one of the most famous scenic mountain areas in China, is renowned for its five wonders: peculiar pines (奇松), grotesque rocks (怪石), a sea of clouds, hot springs, and winter snow. Moun", "tr": "黄山是中国最著名的山岳风景区之一，以五大奇观著称：奇松、怪石、云海、温泉和冬雪。黄山不仅是自然伟力的杰作，也承载着中国丰厚的文化遗产。自古以来，众多文人墨客在作品中赞颂黄山，使它成为中国艺术与文化的一个重要象征。", "pos": "术语", "src": "原文"}, {"term": "grotesque rocks", "zh": "怪石", "q": "Mount Huangshan, one of the most famous scenic mountain areas in China, is renowned for its five wonders: peculiar pines (奇松), grotesque rocks (怪石), a sea of clouds, hot springs, and winter snow. Moun", "tr": "黄山是中国最著名的山岳风景区之一，以五大奇观著称：奇松、怪石、云海、温泉和冬雪。黄山不仅是自然伟力的杰作，也承载着中国丰厚的文化遗产。自古以来，众多文人墨客在作品中赞颂黄山，使它成为中国艺术与文化的一个重要象征。", "pos": "术语", "src": "原文"}, {"term": "Zhangjiajie National Forest Park", "zh": "张家界国家森林公园", "q": "As well as its significant cultural and historical attractions, China has a great many breathtaking natural attractions. Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer spectacular mo", "tr": "除了重要的文化和历史景观，中国还拥有众多令人叹为观止的自然景观。黄山、泰山和天山呈现出壮丽的山峦风光，而九寨沟风景名胜区、张家界国家森林公园和三江源国家公园则拥有中国最令人惊叹的自然景致。", "pos": "其他", "src": "原文"}, {"term": "historical and cultural heritage", "zh": "历史文化遗产", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "national cultural parks", "zh": "国家文化公园", "q": "China, with its long history and rich culture, prioritises the protection of its heritage through comprehensive policies. Investments in national, provincial, and grassroots museums have improved faci", "tr": "中国历史悠长、文化丰厚，通过全面的政策将遗产保护置于优先地位。对国家级、省级和基层博物馆的投入，改善了设施、丰富了展览，也提高了公众的参与度。国家文化公园和国家考古遗址公园也在遗产保护中发挥着关键作用。与此同时，以革命遗产为核心的红色旅游，将历史资源与旅游相结合，以传承革命精神并带动地方经济。这些举措共同保护了中国丰厚的遗产，培育了文化自豪感。", "pos": "其他", "src": "原文"}, {"term": "national archaeological site parks", "zh": "国家考古遗址公园", "q": "China, with its long history and rich culture, prioritises the protection of its heritage through comprehensive policies. Investments in national, provincial, and grassroots museums have improved faci", "tr": "中国历史悠长、文化丰厚，通过全面的政策将遗产保护置于优先地位。对国家级、省级和基层博物馆的投入，改善了设施、丰富了展览，也提高了公众的参与度。国家文化公园和国家考古遗址公园也在遗产保护中发挥着关键作用。与此同时，以革命遗产为核心的红色旅游，将历史资源与旅游相结合，以传承革命精神并带动地方经济。这些举措共同保护了中国丰厚的遗产，培育了文化自豪感。", "pos": "其他", "src": "原文"}, {"term": "historical and cultural museums", "zh": "历史文化博物馆", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "red tourism destinations", "zh": "红色旅游景点", "q": "4 What do you think people can learn from visiting red tourism sites?", "tr": "4 你认为人们参观红色旅游景点能有些什么收获？", "pos": "术语", "src": "原文"}, {"term": "the CCCPC Northwest Bureau", "zh": "中共中央西北局旧址", "q": "China's red tourist attractions are widely distributed across various provinces and regions, including Beijing, Shanghai, Hunan, Jiangxi, and Shaanxi. These sites feature revolutionary landmarks, memo", "tr": "中国的红色旅游景点广泛分布于北京、上海、湖南、江西、陕西等多个省市和地区。这些景点包括革命旧址、纪念馆、烈士陵园，以及其他见证中国革命历史重大事件和人物的场所。其中，延安革命纪念地包括枣园革命旧址、杨家岭革命旧址、中共中央西北局旧址和延安革命纪念馆。这一风景区是延安445处革命旧址中的代表性范例，已被确定为国家爱国主义教育、革命传统教育和“延安精神”的重要教育基地。", "pos": "其他", "src": "原文"}, {"term": "Luoxiao Mountains", "zh": "罗霄山脉", "q": "The Jinggang Mountains Scenic Area in Jiangxi Province is another renowned red tourism destination. The Jinggang Mountains, nestled in the Luoxiao Mountains (罗霄山脉) near the border between Jiangxi and ", "tr": "江西省的井冈山风景区是另一个著名的红色旅游目的地。井冈山坐落于湘赣边界附近的罗霄山脉之中，被誉为中国革命的摇篮。其他热门的红色旅游景点还包括中国人民抗日战争纪念馆、遵义会议纪念馆和辛亥革命武昌起义纪念馆。", "pos": "其他", "src": "原文"}, {"term": "Zunyi Conference Memorial Museum", "zh": "遵义会议纪念馆", "q": "The Jinggang Mountains Scenic Area in Jiangxi Province is another renowned red tourism destination. The Jinggang Mountains, nestled in the Luoxiao Mountains (罗霄山脉) near the border between Jiangxi and ", "tr": "江西省的井冈山风景区是另一个著名的红色旅游目的地。井冈山坐落于湘赣边界附近的罗霄山脉之中，被誉为中国革命的摇篮。其他热门的红色旅游景点还包括中国人民抗日战争纪念馆、遵义会议纪念馆和辛亥革命武昌起义纪念馆。", "pos": "机构", "src": "原文"}, {"term": "red tourism", "zh": "红色旅游", "q": "4 What do you think people can learn from visiting red tourism sites?", "tr": "4 你认为人们参观红色旅游景点能有些什么收获？", "pos": "术语", "src": "原文"}, {"term": "cultural tourism", "zh": "文化旅游", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "sports tourism", "zh": "体育旅游", "q": "The integration of sports into tourism has become a key trend in modern leisure, offering a blend of adventure and relaxation. Hiking in scenic mountain areas, cycling along picturesque routes, and en", "tr": "体育与旅游的融合已成为现代休闲的一大趋势，将探险与放松融为一体。在风景优美的山区徒步、沿着如画的路线骑行，以及参与水上运动，都只是现代旅行将身体活动与探索体验相结合的若干例子。体育旅游的兴起，凸显出人们对既拥有自然美景、又能提供体能挑战机会的目的地兴趣日增。这些趋势展现了一种既重视探险、又重视亲近自然的现代休闲方式。", "pos": "术语", "src": "原文"}, {"term": "city walks", "zh": "城市漫步", "q": "Outdoor activities, such as visiting parks and city walks, have become some of the most popular leisure choices, largely because they are low-cost and relaxing. Additionally, more strenuous activities", "tr": "户外活动，如逛公园、城市漫步，已成为最受欢迎的休闲选择之一，主要原因是它们花费不高且令人放松。此外，跑步、骑行、远足等较为费力的活动正吸引着越来越多的参与者，这一趋势得益于人们对健康与身心福祉重要性的认识不断提高。", "pos": "术语", "src": "原文"}, {"term": "livestream shopping", "zh": "直播购物", "q": "In China, online shopping has become an important part of daily life. By connecting the physical world with the virtual one, online shopping saves people time and energy. According to the 56th Statist", "tr": "在中国，网上购物已成为日常生活的重要组成部分。网上购物将现实世界与虚拟世界连接起来，为人们节省了时间和精力。根据中国互联网络信息中心2025年7月发布的第56次《中国互联网络发展状况统计报告》，截至2025年6月，中国网民规模已超过11.2亿，互联网普及率达79.7%。其中，网上购物平台用户约9.8亿，占网民总数的86.9%。与此同时，直播购物的流行使互动式的网上购物成为一种新的数字娱乐形式。", "pos": "术语", "src": "原文"}, {"term": "cultural and creative industry", "zh": "文化创意产业", "q": "New cultural venues such as creative bazaars, handicraft exhibitions, and cultural and creative industry parks also provide opportunities for people to engage with arts. For example, Shanghai's Tianzi", "tr": "创意集市、手工艺展览、文化创意产业园等新型文化场所，也为人们接触艺术提供了机会。例如，上海的田子坊是一个国际文化创意产业园区，聚集了近400家店铺，包括画廊、工作室、手工艺店、时尚精品店、餐厅和咖啡馆。游客可以欣赏各种独特的艺术品，购买手工艺品，并参加各类创意工坊和艺术讲座。同样，北京的798艺术区吸引着无数艺术家和游客，将昔日的工业场地转变为充满活力的文化中心。", "pos": "术语", "src": "原文"}, {"term": "patriotic education base", "zh": "爱国主义教育基地", "q": "", "tr": "", "pos": "术语", "src": "原文"}, {"term": "third-party payment platform", "zh": "第三方支付平台", "q": "The rapid growth of online shopping in China is closely tied to the security and reliability of the country's leading third-party payment platforms. These platforms offer consumers convenient and secu", "tr": "中国网上购物的快速增长，与国家领先的第三方支付平台的安全性和可靠性密切相关。这些平台为消费者提供便捷、安全的支付方案，增强了人们对在线交易的信心。其强大的基础设施使用户能够安全地购物和支付，使网上购物更加便捷，也推动了网络零售在全国的广泛普及。", "pos": "术语", "src": "原文"}, {"term": "the Yangtze River Delta", "zh": "长江三角洲", "q": "Situated on the southern wing of the Yangtze River Delta, Hangzhou was the capital of the Wuyue Kingdom during the Five Dynasties and Ten Kingdoms period and later became the capital of the Southern S", "tr": "杭州位于长江三角洲的南翼，在五代十国时期是吴越国的都城，后来成为南宋的都城。元朝时，意大利探险家马可·波罗被这座城市的美丽深深打动，称其为“世界上最精美、最高贵的城市”。", "pos": "地理", "src": "原文"}, {"term": "The Palace Museum", "zh": "故宫博物院", "q": "The Palace Museum has released online tour applications, including the Panoramic Palace Museum (全景故宫), the Digital Cultural Relic Library (数字文物库), the Digital Treasure Hall (数字多宝阁), and the Palace Mus", "tr": "故宫博物院推出了多款线上游览应用，包括“全景故宫”“数字文物库”“数字多宝阁”和“故宫展览”。借助这些工具，公众足不出户便能游览故宫博物院、探索其馆藏。即便线下展览结束，用户仍可通过官方网站或博物院的应用继续观展。", "pos": "机构", "src": "原文"}], "vocabB": [], "examsA": [{"term": "", "zh": "", "cn": "过去几年里，移动支付市场在中国蓬勃发展。", "en": "In the past few years, the mobile payment market has been booming in China.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:过去几年里→现在完成时|一般过去;话题:补主语(→the mobile payment market);文化:移动支付→S1 mobile payment（库；CGTN）", "ta": "时间状语前置（连淑能 1993）；补主语（Li & Thompson 1976）；时态呼应（现在完成进行，连淑能 1993）。", "te": "惯用等值（\"蓬勃发展\"→has been booming）；增补（the）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"移动支付\"对应官方短语见 CGTN（mobile payment），S1。", "rp": "`the mobile payment market`（L2·PC）；`in the past few years`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着移动互联网的出现，手机购物逐渐成为一种趋势。", "en": "With the advent of the mobile Internet, mobile shopping has gradually become a trend.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:分句①\"随着…出现\"/②\"手机购物逐渐…\";核心=②;①→时间/背景状语(With the advent of…);触发[随着]→with the advent of…;文化:移动互联网→the mobile Internet（S4 通译）；手机购物→mobile shopping（S4 通译）", "ta": "句首框架状语前置（连淑能 1993）；补主语。", "te": "惯用等值（\"出现\"→the advent of）；增补（gradually）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"移动互联网/手机购物\"库内无同形官方表述，按语境通译，S4。", "rp": "`with the advent of …`（L2·PC）；`become a trend`（L2·PC）。"}, {"term": "", "zh": "", "cn": "18 到 30岁的年轻人构成了移动支付市场的最大群体。", "en": "Young people aged 18 to 30 make up the largest group in the mobile payment market.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:补主语(→Young people aged 18 to 30);文化:移动支付→S1 mobile payment；备注:[原卷如此]（\"18 到 30岁\"数字与\"到\"之间空格，照抄）", "ta": "话题→主语（补主语 Young people，Li & Thompson 1976）；后置定语（aged 18 to 30，连淑能 1993）。", "te": "动词短语（\"构成\"→make up）；增补（aged）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"移动支付\"见 CGTN（S1）。", "rp": "`make up the largest group`（L2·PC）；`aged … to …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "由于现在用手机付款很容易，许多消费者在购物时宁愿用手机付款，而不愿用现金或信用卡。", "en": "As paying with mobile phones is now very easy, many consumers prefer to pay by phone when shopping rather than use cash or credit cards.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:分句①\"由于…很容易\"/②\"许多消费者…宁愿…而不…\";核心=②;①→原因状语从句(As…|Because…);触发[宁愿…而不]→prefer to V rather than V | would rather … than…;文化:信用卡→credit cards（S4 通译）", "ta": "意合→形合（原因状语从句 As…，连淑能 1993）；补主语。", "te": "动词转动名词（\"用手机付款\"→paying with mobile phones，Vinay & Darbelnet 1958）；增补（now）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`prefer to V rather than V`（L2·SB）→ 本句实例：prefer to pay by phone when shopping rather than use cash or credit cards。"}, {"term": "", "zh": "", "cn": "为了鼓励人们多消费，许多商店给使用移动支付的顾客打折。", "en": "To encourage people to spend more, many stores offer discounts to customers who pay by mobile payment.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:分句①\"为了…\"/②\"许多商店…\";核心=②;①→目的状语(To V…)(CL-07);文化:移动支付→S1 mobile payment", "ta": "目的状语前置（连淑能 1993）；意合→形合（\"使用移动支付的顾客\"→定语从句 who…）。", "te": "增补（more）；惯用等值（\"打折\"→offer discounts）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"移动支付\"见 CGTN（S1）。", "rp": "`To V …, 主句`（目的，CL-07）（L2·SB）；`offer discounts to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "专家预测，中国移动支付市场未来仍有很大发展潜力。", "en": "Experts predict that China's mobile payment market still has great potential for development in the future.", "ptype": "真题", "cat": "真题A", "map": "移动支付", "set": "CET4 2018·12·S3", "src": "CET4 2018·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[预测]→predict that…;时锚:未来仍→一般现在|将来;文化:移动支付→S1 mobile payment", "ta": "补主语（Experts）；意合→形合（宾语从句 that…）。", "te": "增补（great）；名词化（\"发展潜力\"→potential for development）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"移动支付\"见 CGTN（mobile payment），S1；\"全球最大的移动支付市场\"库内短语本体标 S4（gov 英文版仅见 front-runner in mobile payment），可互参。", "rp": "`predict that …`（L2·SB）；`potential for development`（L2·PC）。"}, {"term": "", "zh": "", "cn": "过去，乘飞机出行对大多数中国人来说是难以想象的。", "en": "In the past, air travel was unimaginable for most Chinese people.", "ptype": "真题", "cat": "真题A", "map": "乘飞机出行", "set": "CET4 2018·06·S1", "src": "CET4 2018·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:过去→一般过去时;话题:动名词主语(→Flying)|形式主语(It was…);文化:乘飞机出行→S1 air travel|flying（库；China Daily Asia）", "ta": "动名词主语（\"乘飞机出行\"→air travel，连淑能 1993）；时间状语前置。", "te": "词性转换（\"难以想象的\"→unimaginable）；增补（In the past）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"乘飞机出行\"库内作 flying / air travel（China Daily Asia），S1。", "rp": "`be unimaginable for sb`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如今，随着经济的发展和生活水平的提高，越来越多的中国人包括许多农民和外出务工人员都能乘飞机出行。", "en": "Today, with economic development and the improvement of living standards, more and more Chinese people, including many farmers and migrant workers, can now travel by air.", "ptype": "真题", "cat": "真题A", "map": "乘飞机出行", "set": "CET4 2018·06·S1", "src": "CET4 2018·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;①\"随着…提高\"→介词短语(With the development of… and the improvement of…)|As…;时锚:如今→一般现在时;文化:生活水平→S1 living standards（库）；外出务工人员→migrant workers（S4 通译）", "ta": "句首框架状语前置（连淑能 1993）；补主语（Li & Thompson 1976）。", "te": "增补（now, many）；词性转换（\"提高\"→the improvement）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"生活水平\"见官方英文（living standards），S1；\"乘飞机出行\"见 China Daily Asia（flying），S1。", "rp": "`with the improvement of living standards`（L2·PC）；`more and more`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们可以乘飞机到达所有大城市，还有很多城市也在筹建机场。", "en": "They can fly to all big cities, and many more cities are also building airports.", "ptype": "真题", "cat": "真题A", "map": "乘飞机出行", "set": "CET4 2018·06·S1", "src": "CET4 2018·06·S1", "cls": "Chapter 12", "tip": "断句:分句①/②\"还有…\";核心=①;②→并列(and…);时锚:也在→现在进行时;文化:机场→airports（库 S1；China Daily Asia）", "ta": "承前补主语（They）；意合→形合（并列 and，连淑能 1993）。", "te": "增补（also）；动词转进行（\"筹建\"→are building）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"机场\"见 China Daily Asia（airports），S1。", "rp": "`fly to`（L2·PC）；`build airports`（L2·PC）。"}, {"term": "", "zh": "", "cn": "航空服务不断改进，而且经常会有廉价机票。", "en": "Air services are constantly improving, and discounted air tickets are often available.", "ptype": "真题", "cat": "真题A", "map": "乘飞机出行", "set": "CET4 2018·06·S1", "src": "CET4 2018·06·S1", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→并列(and…);时锚:不断→一般现在时;文化:廉价机票→S4 discounted air tickets（库；诚实降级：未定位同形官方表述）", "ta": "意合→形合（并列 and，连淑能 1993）。", "te": "增补（available）；动词转系表（\"有\"→are available）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"廉价机票/特价机票\"库内标 S4（未定位同形官方表述，民航行文多用 budget fares）。", "rp": "`be constantly improving`（L2·PC）；`be available`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来，节假日期间选择乘飞机外出旅游的人数在不断增加。", "en": "In recent years, the number of people choosing to travel by air during public holidays has been increasing.", "ptype": "真题", "cat": "真题A", "map": "乘飞机出行", "set": "CET4 2018·06·S1", "src": "CET4 2018·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:近年来→现在完成|现在进行;文化:节假日→S1 public holidays（库；China Daily Asia）；乘飞机外出旅游→travel by air", "ta": "时间状语前置；后置定语（\"选择…的人数\"→the number of people choosing…，连淑能 1993）。", "te": "增补（In recent years）；动词转动名词（\"选择\"→choosing）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"节假日\"见 China Daily Asia（public holidays），S1。", "rp": "`the number of … choosing to V`（L2·PC）；`during public holidays`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来,越来越多的年轻人喜爱各种形式的自助旅游。", "en": "In recent years, more and more young people have come to enjoy various forms of self-guided travel.", "ptype": "真题", "cat": "真题A", "map": "自助旅游", "set": "CET4 2023·03·S1", "src": "CET4 2023·03·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:近年来→现在完成时;文化:自助旅游→self-guided travel|independent travel（S4 通译）；备注:[原卷如此]（\"近年来,\"后为半角逗号，照抄）", "ta": "时间状语前置；补主语（Li & Thompson 1976）；时态呼应（现在完成，连淑能 1993）。", "te": "增补（come to）；词性转换（\"喜爱\"→enjoy）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"自助旅游\"库内无同形官方定译，按语境通译 self-guided travel（S4）。", "rp": "`more and more`（L2·PC）；`various forms of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "许多自助旅游者选择徒步或骑自行车出游。", "en": "Many self-guided travelers choose to travel on foot or by bicycle.", "ptype": "真题", "cat": "真题A", "map": "自助旅游", "set": "CET4 2023·03·S1", "src": "CET4 2023·03·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;文化:自助旅游者→self-guided travelers（S4）；徒步→on foot|hiking（S4）；骑自行车→cycling（S4）", "ta": "补主语。", "te": "词性转换（\"徒步\"→on foot；\"骑自行车\"→by bicycle）；增补（choose to）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`on foot or by bicycle`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们自己设计路线,自带帐篷、厨具以及其他必备的生活用品。", "en": "They design their own routes and bring tents, cooking utensils and other daily necessities with them.", "ptype": "真题", "cat": "真题A", "map": "自助旅游", "set": "CET4 2023·03·S1", "src": "CET4 2023·03·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[自带]→bring…with them|carry…themselves;文化:帐篷→tents（S4）；厨具→cooking utensils（S4）；生活用品→daily necessities（S4）；备注:[原卷如此]（\"设计路线,\"后为半角逗号，照抄）", "ta": "承前补主语（They）；意合→形合（并列 and，连淑能 1993）。", "te": "增补（their own, with them）；惯用等值（\"生活用品\"→daily necessities）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`design one's own routes`（L2·PC）；`daily necessities`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在旅途中,自助旅游者经常能够发现一些新的美丽景点,但有时也会遇见意想不到的困难或突发事件。", "en": "On their journeys, self-guided travelers can often discover some new and beautiful scenic spots, but sometimes they may also encounter unexpected difficulties or emergencies.", "ptype": "真题", "cat": "真题A", "map": "自助旅游", "set": "CET4 2023·03·S1", "src": "CET4 2023·03·S1", "cls": "Chapter 12", "tip": "断句:分句①/②\"但有时…\";核心=①;②→转折(but…);文化:突发事件→emergencies（S4 通译）；备注:[原卷如此]（两处半角逗号，照抄）", "ta": "句首状语前置；意合→形合（转折 but，连淑能 1993）。", "te": "增补（On their journeys, also）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`scenic spots`（L2·PC）；`encounter unexpected difficulties`（L2·PC）。"}, {"term": "", "zh": "", "cn": "游客在旅行中拥抱自然、欣赏美景,同时也增强了自己克服困难的勇气和野外生存的能力。", "en": "While traveling, tourists embrace nature and enjoy beautiful scenery, while also strengthening their courage to overcome difficulties and their ability to survive in the wild.", "ptype": "真题", "cat": "真题A", "map": "自助旅游", "set": "CET4 2023·03·S1", "src": "CET4 2023·03·S1", "cls": "Chapter 12", "tip": "断句:分句①\"拥抱自然、欣赏美景\"/②\"同时…增强…能力\";核心=①;②→分词状语(while enhancing…)｜并列;文化:野外生存→survival skills in the wild（S4 通译）；备注:[原卷如此]（\"欣赏美景,\"后为半角逗号，照抄）", "ta": "意合→形合（while＋分词状语，连淑能 1993）；补主语。", "te": "动词转动名词（\"生存\"→ability to survive）；增补（their）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`embrace nature`（L2·PC）；`the ability to survive in the wild`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着生活水平的提高，更多人开始加入到自驾游的行列之中。", "en": "As living standards improve, more and more people are beginning to join the ranks of self-driving tourists.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:分句①\"随着…提高\"/②\"更多人…\";核心=②;①→背景状语(As living standards improve|With the improvement of living standards);文化:生活水平→S1 living standards（库）；自驾游→self-driving tours（S4 通译）", "ta": "意合→形合（As 状语从句，连淑能 1993）；补主语。", "te": "增补（are beginning to）；惯用等值（\"行列\"→the ranks of）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"随着生活水平的提高\"库内作 As living standards improve（China Daily 行文），S1；\"自驾游\"按语境通译 self-driving tours（S4）。", "rp": "`As living standards improve`（L2·PC）；`join the ranks of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "自驾游者既可驾驶自家车也可借车或租车出游。", "en": "Self-driving tourists can either drive their own cars or travel in borrowed or rented cars.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:单分句（既…也…）;核心=①;触发[既…也]→both…and…|either…or…;文化:自驾游者→self-driving tourists（S4）", "ta": "补主语；意合→形合（either…or…，连淑能 1993）。", "te": "增补（their own）；词性转换（\"租车\"→rented cars）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`either … or …`（L2·SB）；`borrowed or rented cars`（L2·PC）。"}, {"term": "", "zh": "", "cn": "司机可能是车主或结伴出游者。", "en": "The driver may be the car owner or a fellow traveler.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:补主语(→The driver);文化:车主→the car owner（S4）；结伴出游者→fellow travelers（S4）", "ta": "补主语（Li & Thompson 1976）。", "te": "增补（The）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`the car owner`（L2·PC）。"}, {"term": "", "zh": "", "cn": "自驾游与传统的组团旅游不同,它能够更好地满足旅游者的个性化需求，使他们更好地享受旅游的过程。", "en": "Different from traditional group tours, self-driving tours can better meet the individualized needs of tourists and enable them to better enjoy the travel process.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:分句①\"自驾游与…不同\"/②\"它能够…\";核心=②;①→比较状语(Different from…)|让步;触发[使]→enable+A+to do B|allow+A+to do B;文化:组团旅游→group tours（S4）；个性化需求→individualized needs（S4）；备注:[原卷如此]（\"不同,\"后为半角逗号，照抄）", "ta": "意合→形合（Different from…前置，连淑能 1993）；补主语；使役转移（\"使…\"→enable…to…）。", "te": "增补（better）；词性转换（\"个性化\"→individualized）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`meet the needs of`（L2·PC）；`enable sb to V`（L2·SB）。"}, {"term": "", "zh": "", "cn": "自驾游尤其受到年轻出游者的欢迎。", "en": "Self-driving tours are especially popular among young travelers.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:受事\"自驾游\"→主语;文化:自驾游→self-driving tours（S4）", "ta": "受事主语（话题→主语，Li & Thompson 1976）。", "te": "增补（especially）；词性转换（\"受到欢迎\"→are popular）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`be popular among`（L2·PC）。"}, {"term": "", "zh": "", "cn": "年轻人追求独立自由的生活,而自驾游恰好满足了他们的这一需求。", "en": "Young people pursue an independent and free life, and self-driving tours happen to meet this need of theirs.", "ptype": "真题", "cat": "真题A", "map": "自驾游", "set": "CET4 2023·03·S2", "src": "CET4 2023·03·S2", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→并列对照(and|while);文化:自驾游→self-driving tours（S4）；备注:[原卷如此]（\"生活,\"后为半角逗号，照抄）", "ta": "意合→形合（并列 and，连淑能 1993）；补主语。", "te": "增补（happen to）；惯用等值（\"恰好\"→happen to）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`pursue an independent and free life`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来，越来越多的城市居民为农村的田园风光所吸引,利用节假日到乡村旅游。", "en": "In recent years, more and more urban residents have been attracted by the rural scenery and have visited the countryside during holidays.", "ptype": "真题", "cat": "真题A", "map": "乡村旅游", "set": "CET4 2023·03·S3", "src": "CET4 2023·03·S3", "cls": "Chapter 12", "tip": "断句:分句①\"城市居民为…吸引\"/②\"利用节假日到乡村旅游\";核心=①;②→目的/伴随(to visit rural areas during holidays);触发[为…所]→be attracted by;时锚:近年来→现在完成时;文化:乡村旅游→S1 rural tourism（库；CGTN）；田园风光→rural scenery（S4）；节假日→S1 public holidays（库）；备注:[原卷如此]（\"所吸引,\"后为半角逗号，照抄）", "ta": "受事被动（be attracted by，CL-04）；时间状语前置；意合→形合。", "te": "增补（have visited）；词性转换（\"乡村\"→the countryside）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"乡村旅游\"见 CGTN（rural tourism），S1；\"节假日\"见 China Daily Asia（public holidays），S1。", "rp": "`be attracted by`（L2·PC）；`rural tourism`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们住在农民家中,品尝具有当地风味的农家饭菜。", "en": "They stay in farmers' homes and taste home-style meals with local flavors.", "ptype": "真题", "cat": "真题A", "map": "乡村旅游", "set": "CET4 2023·03·S3", "src": "CET4 2023·03·S3", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→并列(and…);文化:农家饭菜→home-style meals（S4 通译）；备注:[原卷如此]（\"农民家中,\"后为半角逗号，照抄）", "ta": "承前补主语（They）；意合→形合（并列 and，连淑能 1993）。", "te": "增补（with local flavors）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`home-style meals`（L2·PC）；`with local flavors`（L2·PC）。"}, {"term": "", "zh": "", "cn": "有些游客还参与采摘瓜果等活动,亲身感受收获的喜悦。", "en": "Some tourists also take part in activities such as picking fruits and vegetables, experiencing the joy of harvest in person.", "ptype": "真题", "cat": "真题A", "map": "乡村旅游", "set": "CET4 2023·03·S3", "src": "CET4 2023·03·S3", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→分词/目的状语(experiencing…|to experience…);文化:采摘→picking（S4 通译）；备注:[原卷如此]（\"活动,\"后为半角逗号，照抄）", "ta": "意合→形合（分词状语 experiencing…，连淑能 1993）；补主语。", "te": "增补（such as）；惯用等值（\"亲身\"→in person）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`take part in`（L2·PC）；`such as`（L2·PC）。"}, {"term": "", "zh": "", "cn": "乡村旅游能够有效地帮助游客舒缓压力,放松心情,增进身心健康。", "en": "Rural tourism can effectively help tourists relieve stress, relax and improve their physical and mental health.", "ptype": "真题", "cat": "真题A", "map": "乡村旅游", "set": "CET4 2023·03·S3", "src": "CET4 2023·03·S3", "cls": "Chapter 12", "tip": "断句:单分句（多项动宾）;核心=①;文化:乡村旅游→S1 rural tourism；身心健康→physical and mental health（S4）；备注:[原卷如此]（\"舒缓压力,\"后为半角逗号，照抄）", "ta": "补主语；意合→形合（并列动词）。", "te": "增补（effectively, their）；词性转换（\"身心\"→physical and mental）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"乡村旅游\"见 CGTN（rural tourism），S1。", "rp": "`relieve stress`（L2·PC）；`physical and mental health`（L2·PC）。"}, {"term": "", "zh": "", "cn": "实际上,这种旅游形式不仅能使城市游客受益,同时也能增加农民的收入,促进农村经济发展。", "en": "In fact, this form of tourism can not only benefit urban tourists but also increase farmers' incomes and promote rural economic development.", "ptype": "真题", "cat": "真题A", "map": "乡村旅游", "set": "CET4 2023·03·S3", "src": "CET4 2023·03·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[不仅…同时…]→not only…but also…；文化:农村经济→rural economy（S4）；增收（农民增收）→increase farmers' incomes（库 S1）；备注:[原卷如此]（三处半角逗号，照抄）", "ta": "意合→形合（not only… but also…，连淑能 1993）；补主语。", "te": "增补（In fact）；动词\"受益/增加/促进\"→benefit / increase / promote。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"增收（农民增收）\"官方行文 increase farmers' incomes（China Daily 每日一词），S1。", "rp": "`not only … but also …`（L2·SB）；`increase farmers' incomes`（L2·PC）。"}, {"term": "", "zh": "", "cn": "“城市漫步 (city walk)”在中国的年轻人中悄然兴起，已成为一种旅游新潮流。", "en": "\"City walk\" has quietly emerged among young people in China and has become a new tourism trend.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=②;①→时间/伴随;时锚:已→现在完成时;文化:城市漫步→S1 city walk（库；CGTN/China Daily；原卷括注 city walk；教材术语增补 city walks）；旅游新潮流→a new tourism trend（S4）", "ta": "话题/主语前置（引号术语作主语，Li & Thompson 1976）；时态呼应（现在完成，连淑能 1993）；意合→形合（并列 and）。", "te": "增补（quietly）；词性转换（\"兴起\"→has emerged）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"城市漫步\"官方短语 city walk 见 CGTN/China Daily（S1）；原卷括注 city walk 同源。", "rp": "`city walk`（L2·PC）；`become a new trend`（L2·PC）。"}, {"term": "", "zh": "", "cn": "与传统旅游近年来，不同，城市漫步不追求在短时间内游览尽可能多的景点。", "en": "Different from traditional tourism, city walk does not seek to visit as many attractions as possible in a short time.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;①\"与…不同\"→介词/分词短语(Different from…);文化:传统旅游→traditional tourism（S4）；备注:[原卷如此]（\"与传统旅游近年来，不同\"语序错乱，\"近年来\"疑为混入，照抄不改）", "ta": "意合→形合（Different from…前置，连淑能 1993）；补主语。", "te": "增补（Different from）；惯用等值（\"尽可能多的\"→as many … as possible）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"城市漫步\"见 CGTN/China Daily（city walk），S1。", "rp": "`Different from …`（L2·PC）；`as many … as possible`（L2·PC）。"}, {"term": "", "zh": "", "cn": "而是随意行走或按照主题路线漫步在城市的大街小巷。", "en": "Instead, they wander at will or stroll along themed routes through the streets and alleys of the city.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;①\"而是…\"→并列谓语(Instead, …)|承接前句;文化:主题路线→themed routes（S4）；大街小巷→streets and alleys（库 S4 通译）；备注:[原卷如此]（\"而是\"承接前句，原样保留）", "ta": "补主语（they）；意合→形合（Instead 承接，连淑能 1993）。", "te": "增补（Instead, along）；惯用等值（\"随意\"→at will）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"大街小巷\"库内作 streets and alleys（S4 通译）。", "rp": "`at will`（L2·PC）；`streets and alleys`（L2·PC）。"}, {"term": "", "zh": "", "cn": "漫步者品尝地道小吃，欣赏特色建筑，了解当地生活方式。", "en": "Walkers taste authentic local snacks, admire historic buildings and learn about the local way of life.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:单分句（多项动宾）;核心=①;文化:地道小吃→S1 authentic local snacks（库；Shenzhen Daily）；特色建筑→S1 historic buildings（库；Shenzhen Daily）", "ta": "补主语（Walkers）；意合→形合（并列动词）。", "te": "增补（authentic, local）；词性转换（\"漫步者\"→walkers）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"地道小吃\"见 Shenzhen Daily（authentic local snacks），S1；\"特色建筑\"库内作 historic buildings（Shenzhen Daily），S1。", "rp": "`authentic local snacks`（L2·PC）；`learn about`（L2·PC）。"}, {"term": "", "zh": "", "cn": "他们还用相机或手机记录城市的风景和人物。", "en": "They also use cameras or mobile phones to record the city's scenery and people.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:补主语(→They)", "ta": "承前补主语（They）。", "te": "增补（also）；词性转换（\"人物\"→people）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`use … to record …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "这种旅游方式能让城市漫步者更深入了解城市的历史与文化。", "en": "This way of traveling enables city walkers to gain a deeper understanding of the city's history and culture.", "ptype": "真题", "cat": "真题A", "map": "城市漫步", "set": "CET4 2025·12·S2", "src": "CET4 2025·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[让]→enable+A+to do B|allow+A+to do B;文化:城市漫步者→city walkers（S4）", "ta": "补主语；使役转移（\"让…\"→enable…to…，连淑能 1993）。", "te": "词性转换（\"深入了解\"→gain a deeper understanding of）；增补（This way）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"城市漫步\"见 CGTN/China Daily（city walk），S1。", "rp": "`enable sb to V`（L2·SB）；`gain a deeper understanding of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来，中国东北地区正在大力开发冰雪资源。", "en": "In recent years, Northeast China has been vigorously developing its ice and snow resources.", "ptype": "真题", "cat": "真题A", "map": "冰雪资源与冰雪旅游", "set": "CET4 2025·06·S3", "src": "CET4 2025·06·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:近年来/正在→现在进行时;文化:东北地区→Northeast China（库 S4）；冰雪资源→ice and snow resources（库 S4）", "ta": "时间状语前置；补主语；时态呼应（现在进行，连淑能 1993）。", "te": "增补（vigorously, its）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"东北地区\"库内作 Northeast China（S4），\"冰雪资源\"作 ice and snow resources（S4）。", "rp": "`develop ice and snow resources`（L2·PC）。"}, {"term": "", "zh": "", "cn": "例如，哈尔滨利用丰富的冰雪资源打造了极具地方特色的“冰雪大世界”，让游客在欣赏冰雪之美的同时也能体验当地独特的民俗文化。", "en": "For example, Harbin has used its rich ice and snow resources to create the highly distinctive \"Harbin Ice-Snow World,\" enabling visitors to enjoy the beauty of ice and snow while experiencing the area's unique folk culture.", "ptype": "真题", "cat": "真题A", "map": "冰雪资源与冰雪旅游", "set": "CET4 2025·06·S3", "src": "CET4 2025·06·S3", "cls": "Chapter 12", "tip": "断句:分句①\"例如…冰雪大世界\"/②\"让游客…\";核心=①;②→分词/结果状语(letting…)|enable…to…;触发[使]→enable+A+to do B|allow+A+to do B;文化:哈尔滨→Harbin（专名）；冰雪大世界→S1 Harbin Ice-Snow World（库；China Daily）；民俗文化→S1 folk culture（库）", "ta": "补主语；使役转移（\"让…\"→enabling…to…，连淑能 1993）；分词状语（连淑能 1993）。", "te": "增补（highly, while）；词性转换（\"欣赏冰雪之美\"→enjoy the beauty of ice and snow）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"冰雪大世界\"专名 Harbin Ice-Snow World 见 China Daily（S1）；\"民俗文化\"库内作 folk culture（S1）。", "rp": "`enable sb to V`（L2·SB）；`folk culture`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如今，曾令人畏惧的冰天雪地正吸引着四面八方的游客，成为深受欢迎的旅游胜地。", "en": "Today, the once-feared icy world is attracting tourists from near and far and has become a popular tourist destination.", "ptype": "真题", "cat": "真题A", "map": "冰雪资源与冰雪旅游", "set": "CET4 2025·06·S3", "src": "CET4 2025·06·S3", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→分词状语(becoming…)|并列;时锚:如今/正→现在进行时;文化:四面八方的游客→S1 tourists from near and far（库；China Daily Asia）；旅游胜地→a popular tourist destination（库 S4）", "ta": "时间状语前置；补主语；意合→形合（并列 and，连淑能 1993）。", "te": "增补（once-feared, has）；词性转换（\"冰天雪地\"→the icy world）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"四面八方的游客\"库内作 tourists from near and far（China Daily Asia），S1；\"旅游胜地\"库内作 a popular tourist destination（S4）。", "rp": "`tourists from near and far`（L2·PC）；`a popular tourist destination`（L2·PC）。"}, {"term": "", "zh": "", "cn": "冰雪旅游业正为当地的经济发展做出越来越大的贡献。", "en": "The ice and snow tourism industry is making an ever-greater contribution to the local economy.", "ptype": "真题", "cat": "真题A", "map": "冰雪资源与冰雪旅游", "set": "CET4 2025·06·S3", "src": "CET4 2025·06·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:正→现在进行时;触发[做出…贡献]→make an ever-greater contribution to;文化:冰雪旅游业→the ice and snow tourism industry（S4）", "ta": "补主语；时态呼应（现在进行，连淑能 1993）。", "te": "词性转换（\"经济发展\"→the local economy）；增补（ever-greater）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"做出越来越大的贡献\"库内作 make an ever-greater contribution to（S4）。", "rp": "`make an ever-greater contribution to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府十分重视环境保护。", "en": "The Chinese government attaches great importance to environmental protection.", "ptype": "真题", "cat": "真题A", "map": "环境保护与垃圾分类", "set": "CET4 2024·12·S1", "src": "CET4 2024·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;文化:高度重视→attach great importance to（库 S1）；环境保护→environmental protection（库 S1）", "ta": "补主语。", "te": "惯用等值（\"十分重视\"→attaches great importance to，Vinay & Darbelnet 1958）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"高度重视\"见 scio 行文，\"环境保护\"见 China Daily（S1）。", "rp": "`attach great importance to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "近年来，中国在减少空气、水和土壤污染上取得了显著成效。", "en": "In recent years, China has achieved remarkable results in reducing air, water and soil pollution.", "ptype": "真题", "cat": "真题A", "map": "环境保护与垃圾分类", "set": "CET4 2024·12·S1", "src": "CET4 2024·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:近年来→现在完成时;文化:空气、水和土壤污染→air, water and soil pollution（库 S1）", "ta": "时间状语前置；补主语。", "te": "增补（remarkable）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"空气、水和土壤污染\"官方三项并列见二十大英文站 / China Daily（S1）。", "rp": "`achieve remarkable results in`（L2·PC）。"}, {"term": "", "zh": "", "cn": "为了不断改善人们的生活环境，中国采取了一系列有效措施，包括大力发展清洁能源，改善公共交通，推广共享单车，实施垃圾分类。", "en": "To continuously improve people's living environment, China has taken a series of effective measures, including vigorously developing clean energy, improving public transport, promoting shared bikes and implementing garbage sorting.", "ptype": "真题", "cat": "真题A", "map": "环境保护与垃圾分类", "set": "CET4 2024·12·S1", "src": "CET4 2024·12·S1", "cls": "Chapter 12", "tip": "断句:分句①\"为了…\"/②\"中国采取…\";核心=②;①→目的状语(To V…)(CL-07);文化:清洁能源→clean energy（库 S1）；共享单车→shared bikes（库 S1）；垃圾分类→garbage sorting（库 S1）", "ta": "目的状语前置（连淑能 1993）；分词列举（including…）。", "te": "增补（vigorously, a series of）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"清洁能源/共享单车/垃圾分类\"均见 China Daily / CGTN（S1）。", "rp": "`take a series of measures`（L2·PC）；`including V-ing …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "通过这些措施，中国的城市和农村正在绿起来、美起来。", "en": "Through these measures, China's cities and countryside are becoming greener and more beautiful.", "ptype": "真题", "cat": "真题A", "map": "环境保护与垃圾分类", "set": "CET4 2024·12·S1", "src": "CET4 2024·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;①\"通过…\"→方式状语(Through…);时锚:正在→现在进行时", "ta": "方式状语前置（连淑能 1993）。", "te": "惯用等值（\"绿起来、美起来\"→are becoming greener and more beautiful）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`become greener and more beautiful`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国还积极参与国际合作，为全球环境保护做出了重要贡献。", "en": "China has also actively participated in international cooperation and made important contributions to global environmental protection.", "ptype": "真题", "cat": "真题A", "map": "环境保护与垃圾分类", "set": "CET4 2024·12·S1", "src": "CET4 2024·12·S1", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=①;②\"为…做出贡献\"→make contributions to…;时锚:已→现在完成时;文化:国际合作→international cooperation", "ta": "补主语；意合→形合（并列谓语，连淑能 1993）。", "te": "增补（important）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"环境保护\"见 China Daily（S1）。", "rp": "`make important contributions to`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府十分重视绿色经济的发展。", "en": "The Chinese government attaches great importance to the development of the green economy.", "ptype": "真题", "cat": "真题A", "map": "绿色经济与生态文明", "set": "CET4 2025·12·S3", "src": "CET4 2025·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;文化:高度重视…的发展→attach great importance to the development of…（库 S1）；绿色经济→the green economy（库 S1）", "ta": "补主语。", "te": "惯用等值（\"十分重视\"→attaches great importance to）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"绿色经济\"见 CCTV 英版（S1），\"高度重视…的发展\"见 scio 行文（S1）。", "rp": "`attach great importance to the development of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "通过加强森林资源保护、加大污染治理力度等一系列措施，许多地区的生态环境得到了显著改善。", "en": "Through a series of measures such as strengthening forest resource protection and intensifying pollution control, the ecological environment in many regions has been significantly improved.", "ptype": "真题", "cat": "真题A", "map": "绿色经济与生态文明", "set": "CET4 2025·12·S3", "src": "CET4 2025·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;①\"通过…措施\"→方式状语(Through…);话题:受事\"生态环境\"→被动(has been improved);时锚:得到了→现在完成时;文化:生态环境→the ecological environment", "ta": "方式状语前置（连淑能 1993）；受事主语→被动（CL-04）。", "te": "增补（such as, a series of）；词性转换（\"保护/治理\"→protection/control）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`a series of measures such as …`（L2·PC）；`has been significantly improved`（L2·PC）。"}, {"term": "", "zh": "", "cn": "绿水青山 (lucid waters and lush mountains) 促进了当地的旅游、健康等产业的发展，创造了可观的经济效益。", "en": "Lucid waters and lush mountains have boosted the development of local tourism, healthcare and other industries, creating considerable economic benefits.", "ptype": "真题", "cat": "真题A", "map": "绿色经济与生态文明", "set": "CET4 2025·12·S3", "src": "CET4 2025·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;②\"创造了…\"→分词状语(creating…)(CL-03);文化:绿水青山→lucid waters and lush mountains（库 S1 定译；原卷括注同源）", "ta": "分词状语（creating…，连淑能 1993）。", "te": "增补（considerable）；词性转换（\"健康\"→healthcare）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"绿水青山\"官方定译 lucid waters and lush mountains（新华英版 / China Daily，S1；原卷括注同源）。", "rp": "`create considerable economic benefits`（L2·PC）；`V-ing 结果状语`（L2·SB）。"}, {"term": "", "zh": "", "cn": "如今，生态环境与人类社会和谐共存的观念在中国已深入人心。", "en": "Today, the idea of harmonious coexistence between the ecological environment and human society has taken root in the hearts of the Chinese people.", "ptype": "真题", "cat": "真题A", "map": "绿色经济与生态文明", "set": "CET4 2025·12·S3", "src": "CET4 2025·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:如今/已→现在完成时;文化:和谐共存→harmonious coexistence（库：与自然和谐共存 live in harmony with nature，S1）；深入人心→take root in the hearts of", "ta": "补主语（the idea…，Li & Thompson 1976）。", "te": "惯用等值（\"深入人心\"→has taken root in the hearts of）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"和谐共存\"见官方生态文明行文（S1）。", "rp": "`take root in the hearts of`（L2·PC）；`harmonious coexistence`（L2·PC）。"}, {"term": "", "zh": "", "cn": "绿色经济的推进不仅能为中国可持续发展做出贡献，也为全球环境保护提供了宝贵经验。", "en": "Advancing the green economy can not only contribute to China's sustainable development but also provide valuable experience for global environmental protection.", "ptype": "真题", "cat": "真题A", "map": "绿色经济与生态文明", "set": "CET4 2025·12·S3", "src": "CET4 2025·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[不仅…也]→not only…but also…;文化:可持续发展→sustainable development（库 S1）；绿色经济→the green economy（库 S1）", "ta": "动名词主语（\"绿色经济的推进\"→Advancing the green economy，连淑能 1993）。", "te": "增补（valuable）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"可持续发展\"为官方关键词（S1），\"绿色经济\"见 CCTV 英版（S1）。", "rp": "`not only … but also …`（L2·SB）；`contribute to`（L2·PC）。"}], "examsB": [{"term": "", "zh": "", "cn": "随着经济与社会的发展，中国人口结构发生了显著变化，逐渐步入老龄化社会。", "en": "With the development of the economy and society, China's population structure has undergone significant changes, and the country has gradually entered an aging society.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:单分句（含\"随着\"框架状语）;核心=主句;触发[随着]→With+NP|As…（时间/背景状语）;时锚:发生了/步入→现在完成时;文化:老龄化社会→an aging society（库 S1）", "ta": "意合→形合（\"随着\"框架状语前置，连淑能 1993）；补主语（the country，Li & Thompson 1976）。", "te": "词性转换（\"发展\"→the development）；惯用等值（\"步入\"→entered）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"老龄化社会\"对应官方短语见 gov 英文版 / China Daily（an aging society），S1。", "rp": "`with the development of …`（L2·PC）；`an aging society`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国老年人口将持续增加，人口老龄化趋势将更加明显。", "en": "China's elderly population will keep increasing, and the trend of population aging will become even more evident.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:并列两分句;核心=①;②→并列(and);时锚:将→一般将来时;文化:老年人口→the elderly population；人口老龄化→population aging（库）", "ta": "意合→形合（并列 and，连淑能 1993）；时态呼应（将来时，连淑能 1993）。", "te": "增补（even）；词性转换（\"趋势\"→the trend）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"老龄化\"对应官方短语见 gov 英文版（S1）。", "rp": "`keep increasing`（L2·PC）；`the trend of population aging`（L2·PC）。"}, {"term": "", "zh": "", "cn": "为了应对人口老龄化带来的种种挑战，国家正积极采取措施，加大对养老的支持。", "en": "To address the various challenges brought by population aging, the country is actively taking measures to increase support for elderly care.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:分句①\"为了应对…挑战\"/②\"国家正…\";核心=②;①→目的状语(To V…)(CL-07);时锚:正→现在进行时;触发[加大支持]→increase support for;文化:养老→elderly care（库）", "ta": "目的状语前置（连淑能 1993）；补主语（the country）。", "te": "增补（various）；词性转换（\"支持\"→support）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"养老\"对应官方短语见 gov 英文版（the elderly care service system），S1。", "rp": "`take measures to V`（L2·SB）→ 本句实例：the country is actively taking measures to increase support for elderly care；`increase support for`（L2·PC）。"}, {"term": "", "zh": "", "cn": "通过改革社会保障 (social security) 制度，政府不断增加社会保障经费，逐步扩大社会保障覆盖范围，使更多老年人受益。", "en": "By reforming the social security system, the government has kept increasing funding for social security and gradually expanded its coverage, benefiting more elderly people.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:单分句（多项谓语串）;核心=主句;①\"通过…\"→方式状语(by V-ing);触发[使]→V-ing 分词(benefiting)|enable+A+to do B;时锚:不断增加/扩大→现在完成时;文化:社会保障→social security（原卷括注，同源优先）", "ta": "方式状语前置（by＋动名词，连淑能 1993）；意合→形合。", "te": "动词转动名词（\"改革\"→reforming，Vinay & Darbelnet 1958）；增补（funding / its coverage）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"社会保障\"取原卷括注 social security（同源优先）。", "rp": "`By V-ing …, S + V …`（L2·SB）→ 本句实例：By reforming the social security system, the government has kept increasing funding …；`expand coverage`（L2·PC）。"}, {"term": "", "zh": "", "cn": "政府还鼓励各种社会团体为老年人提供服务。", "en": "The government also encourages various social organizations to provide services for the elderly.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[鼓励…为…提供]→encourage+A+to do B;文化:社会团体→social organizations", "ta": "补主语（承前 the government）。", "te": "增补（various）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`encourage sb to do sth`（L2·SB）。"}, {"term": "", "zh": "", "cn": "在政府和社会团体的共同努力下，老年人将生活得更加幸福。", "en": "With the joint efforts of the government and social organizations, the elderly will live a happier life.", "ptype": "真题", "cat": "真题B", "map": "老龄化与养老", "set": "CET6 2023·12·S1", "src": "CET6 2023·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;①\"在…下\"→状语(With+NP);时锚:将→一般将来时;文化:老年人→the elderly", "ta": "句首框架状语前置（连淑能 1993）；补主语。", "te": "词性转换（\"幸福\"→a happier life，Vinay & Darbelnet 1958）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`with the joint efforts of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在中国，随着老龄化社会的到来，养老受到普遍关注。", "en": "In China, with the advent of an aging society, the issue of elderly care has drawn widespread attention.", "ptype": "真题", "cat": "真题B", "map": "养老模式", "set": "CET6 2023·12·S2", "src": "CET6 2023·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;触发[随着…的到来]→with the advent of…;话题:受事\"养老\"→话题转主语(the issue of elderly care);时锚:受到→现在完成时;文化:老龄化社会→an aging society（库 S1）", "ta": "话题→主语（受事\"养老\"→the issue of elderly care，Li & Thompson 1976）；句首状语前置。", "te": "词性转换（\"受到关注\"→has drawn attention）；惯用等值（\"到来\"→the advent）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"老龄化社会\"对应官方短语见 gov 英文版（S1）。", "rp": "`draw widespread attention`（L2·PC）；`with the advent of …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "人们谈论最多的是应当采取什么样的养老模式。", "en": "What people talk about most is what kind of elderly care model should be adopted.", "ptype": "真题", "cat": "真题B", "map": "养老模式", "set": "CET6 2023·12·S2", "src": "CET6 2023·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:话题句→what 主语从句(What people talk about most);触发[应当采取]→should be adopted（受事被动）", "ta": "话题转主语（what-从句，Li & Thompson 1976）；受事→被动（should be adopted，CL-04）。", "te": "增补（model）；名词化（\"采取\"→adopted）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`What … is what …`（L2·SB）→ 本句实例：What people talk about most is what kind of elderly care model should be adopted。"}, {"term": "", "zh": "", "cn": "多数人认为，养老模式需要多元化。", "en": "Most people believe that elderly care models need to be diversified.", "ptype": "真题", "cat": "真题B", "map": "养老模式", "set": "CET6 2023·12·S2", "src": "CET6 2023·12·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[认为]→believe that…;名词化(\"多元化\")", "ta": "补主语（Most people）。", "te": "词性转换（\"多元化\"→be diversified，Molina & Albir 2002）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`believe that …`（L2·SB）。"}, {"term": "", "zh": "", "cn": "可以通过政府引导和社会参与，建立更多更好的养老服务机构，改进社区服务中心，鼓励居家自助养老，还可以推行家庭养老与社会养老相结合的模式。", "en": "Through government guidance and social participation, we can establish more and better elderly care service institutions, improve community service centers, encourage home-based self-care, and also promote a model that combines family care with social care.", "ptype": "真题", "cat": "真题B", "map": "养老模式", "set": "CET6 2023·12·S2", "src": "CET6 2023·12·S2", "cls": "Chapter 12", "tip": "断句:单分句（多项动宾）;核心=①;①\"通过…\"→方式状语(through…);话题:无主句→补主语(we/they);触发[相结合]→combine A with B|a model that combines…;文化:居家养老→home-based care；社会养老→social care", "ta": "补主语（无主句→we，Li & Thompson 1976）；意合→形合（并列谓语）。", "te": "增补（more and better）；词性转换（\"相结合\"→combines…with…）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"养老服务\"对应官方短语见 gov 英文版（S1）。", "rp": "`a model that combines A with B`（L2·SB）；`home-based self-care`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着政府和社会对养老服务事业投入的持续增加，养老设施将不断升级，服务质量逐步改进，老年人的生活将会更加方便舒适、健康快乐。", "en": "As the government and society continue to increase their investment in elderly care services, care facilities will be constantly upgraded, service quality will gradually improve, and the lives of the elderly will become more convenient, comfortable, healthy and happy.", "ptype": "真题", "cat": "真题B", "map": "养老模式", "set": "CET6 2023·12·S2", "src": "CET6 2023·12·S2", "cls": "Chapter 12", "tip": "断句:分句①\"随着…增加\"/②\"养老设施将…\";核心=②;①→As 伴随状语从句;时锚:将→一般将来时;文化:养老服务事业→elderly care services", "ta": "意合→形合（As 引导伴随状语从句，连淑能 1993）；时态呼应（将来时）。", "te": "增补（their）；受事被动（\"升级\"→be upgraded，CL-04）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`As …, … will …`（L2·SB）。"}, {"term": "", "zh": "", "cn": "近年来，中国老龄人口持续增长。", "en": "In recent years, China's elderly population has continued to grow.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:近年来→现在完成时;文化:老龄人口→the elderly population", "ta": "时间状语前置（连淑能 1993）；补主语。", "te": "增补（continued）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`in recent years`（L2·PC）；`continue to grow`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府正采取各种措施，推进养老服务体系建设，使老年人晚年生活健康幸福。", "en": "The Chinese government is taking various measures to advance the building of an elderly care service system and ensure that the elderly live a healthy and happy life in their later years.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=主句;触发[使]→ensure that…|V-ing 分词;时锚:正→现在进行时;文化:养老服务体系→the elderly care service system（库 S1）；晚年→later years", "ta": "补主语；意合→形合（目的/结果→to V… and ensure…，连淑能 1993）。", "te": "增补（various）；动词转名词（\"建设\"→the building）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"养老服务体系\"对应官方短语见 gov 英文版（S1）。", "rp": "`take measures to V`（L2·SB）；`live a … life in their later years`（L2·PC）。"}, {"term": "", "zh": "", "cn": "全国兴建了各类养老服务机构。", "en": "Various elderly care service institutions have been built across the country.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:无主句→受事被动(have been built)|补主语;文化:养老服务机构→elderly care service institutions", "ta": "受事主语→被动（CL-04）；补主语（施事省略）。", "te": "增补（various, across the country）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`have been built across the country`（L2·PC）。"}, {"term": "", "zh": "", "cn": "为了提升养老机构的服务质量，政府颁布了一系列标准，加强对养老机构的监管。", "en": "To improve the service quality of elderly care institutions, the government has issued a series of standards to strengthen supervision over them.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:分句①\"为了…质量\"/②\"政府颁布…监管\";核心=②;①→目的状语(To V…)(CL-07);时锚:颁布了→现在完成时;文化:养老机构→elderly care institutions", "ta": "目的状语前置（连淑能 1993）。", "te": "增补（a series of）；词性转换（\"监管\"→supervision）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`issue a series of standards`（L2·PC）；`strengthen supervision over`（L2·PC）。"}, {"term": "", "zh": "", "cn": "许多城市为方便老年人用餐，开设了社区食堂，为他们提供价格实惠的饭菜。", "en": "To make it easier for the elderly to have meals, many cities have opened community canteens offering them affordable food.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=主句;①\"为方便…用餐\"→目的状语(To make it easier for sb to do…);文化:社区食堂→community canteens（库 S1）", "ta": "目的状语前置（连淑能 1993）。", "te": "增补（affordable）；分词短语（offering…，连淑能 1993）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"社区食堂\"对应官方短语见 gov 英文版（S1）。", "rp": "`community canteens`（L2·PC）；`To make it easier for sb to V`（L2·SB）。"}, {"term": "", "zh": "", "cn": "行动不便的老年人还能享受上门送餐服务。", "en": "Elderly people with limited mobility can also enjoy door-to-door meal delivery services.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:补主语(→the elderly);文化:上门送餐→door-to-door meal delivery", "ta": "定语后置（\"行动不便的\"→with limited mobility，连淑能 1993）。", "te": "词性转换；增补（services）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`with limited mobility`（L2·PC）；`door-to-door … services`（L2·PC）。"}, {"term": "", "zh": "", "cn": "同时，中国还在积极探索居家和社区养老等其他养老模式，以确保所有老年人老有所养。", "en": "Meanwhile, China is also actively exploring other elderly care models such as home-based and community-based care, to ensure that all elderly people are well provided for.", "ptype": "真题", "cat": "真题B", "map": "养老服务体系建设", "set": "CET6 2023·12·S3", "src": "CET6 2023·12·S3", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;①\"以确保…\"→目的状语(to ensure…)(CL-07);时锚:还在→现在进行时;文化:居家和社区养老→home-based and community-based care；老有所养→be well provided for", "ta": "目的状语后置（连淑能 1993）。", "te": "增补（such as, well）；惯用等值（\"老有所养\"→be well provided for）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`such as …`（L2·PC）；`ensure that …`（L2·SB）。"}, {"term": "", "zh": "", "cn": "2011 年是中国城市化 (urbanization)进程中的历史性时刻，其城市人口首次超过农村人口。", "en": "2011 was a historic moment in China's urbanization process, when its urban population exceeded its rural population for the first time.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→定语从句(when…);时锚:2011年→一般过去时;文化:城市化→urbanization（原卷括注，同源优先；库 S1 中国政府网英文版）", "ta": "意合→形合（②非限制定语从句 when…，连淑能 1993）。", "te": "增补（for the first time）；词性转换（\"进程\"→process）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"城市化\"取原卷括注 urbanization，并见中国政府网英文版（S1）。", "rp": "`a historic moment in …`（L2·PC）；`exceed … for the first time`（L2·PC）。"}, {"term": "", "zh": "", "cn": "在未来 20 年里，预计约有 3.5 亿农村人口将移居到城市。", "en": "In the next 20 years, about 350 million rural people are expected to move to cities.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:话题句→被动构式(are expected to)；时锚:将→一般将来时", "ta": "补主语＋被动构式（are expected to，CL-04）；句首时间状语前置。", "te": "增补（about）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`be expected to V`（L2·SB）。"}, {"term": "", "zh": "", "cn": "如此规模的城市发展对城市交通来说既是挑战，也是机遇。", "en": "Urban development on such a scale is both a challenge and an opportunity for urban transport.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[既…也]→both A and B;话题:话题\"城市发展\"→主语", "ta": "话题→主语（Li & Thompson 1976）；修饰语位序（\"如此规模的\"→on such a scale 后置，连淑能 1993）。", "te": "惯用等值（\"既是…也是\"→both … and …）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`both A and B`（L2·SB）；`on such a scale`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国政府一直提倡“以人为本”的发展理念，强调人们以公交而不是私家车出行。", "en": "The Chinese government has long advocated a \"people-oriented\" development philosophy, emphasizing that people should travel by public transport rather than by private cars.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=主句;②\"强调…\"→分词状语(emphasizing…)；触发[而不是]→rather than;时锚:一直→现在完成时;文化:以人为本→people-oriented（中国政府网英文版，S1）；公交→public transport（库 S1）", "ta": "意合→形合（分词状语，连淑能 1993）；补主语。", "te": "增补（should）；动词转名词（\"提倡\"→has advocated）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"以人为本\"官方行文 people-oriented / people-centered（中国政府网英文版，S1）；\"公交\"见 China Daily（public transport），S1。", "rp": "`rather than`（L2·PC）；`advocate a … philosophy`（L2·PC）。"}, {"term": "", "zh": "", "cn": "它还号召建设“资源节约和环境友好型”社会。", "en": "It also calls for building a \"resource-conserving and environment-friendly\" society.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;文化:资源节约和环境友好型→resource-conserving and environment-friendly（官方定译行文）", "ta": "补主语（承前 It）。", "te": "增补（building）；复合形容词（\"资源节约和环境友好型\"→resource-conserving and environment-friendly）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"资源节约型、环境友好型社会\"官方定式见中国政府网英文版（S1）。", "rp": "`call for doing sth`（L2·PC）；`a resource-conserving and environment-friendly society`（L2·PC）。"}, {"term": "", "zh": "", "cn": "有了这个明确的目标，中国城市就可以更好地规划其发展，并把大量投资转向安全、清洁和经济型交通系统的发展上。", "en": "With this clear goal, Chinese cities can better plan their development and direct large investments toward developing safe, clean and economical transport systems.", "ptype": "真题", "cat": "真题B", "map": "城市化", "set": "CET6 2015·06·S2", "src": "CET6 2015·06·S2", "cls": "Chapter 12", "tip": "断句:分句①\"有了…目标\"/②\"城市就可以…\";核心=②;①→With+NP 状语;触发[转向]→direct…toward…;文化:交通系统→transport systems", "ta": "句首框架状语前置（连淑能 1993）；意合→形合（并列谓语）。", "te": "增补（their, large）；动词\"转向\"→direct … toward…。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`direct … toward …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着生活水平的提高，度假在中国人生活中的作用越来越重要。", "en": "With the improvement of living standards, vacations are playing an increasingly important role in the lives of Chinese people.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:分句①\"随着…提高\"/②\"度假…越来越重要\";核心=②;①→背景状语(With the improvement of…|As living standards improve);文化:生活水平→S1 living standards（库）；度假→vacation（S4 通译）", "ta": "句首框架状语前置（连淑能 1993）；补主语。", "te": "增补（increasingly）；词性转换（\"作用\"→role）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"生活水平\"见官方英文（living standards），S1。", "rp": "`play an increasingly important role in`（L2·PC）。"}, {"term": "", "zh": "", "cn": "过去，中国人的时间主要花在谋生上，很少有机会外出旅行。", "en": "In the past, Chinese people spent most of their time making a living and had few opportunities to travel.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:分句①/②\"很少有机会…\";核心=①;②→并列(and…)|结果;时锚:过去→一般过去时;文化:谋生→making a living（S4 通译）", "ta": "时间状语前置；承前补主语；意合→形合（并列 and，连淑能 1993）。", "te": "惯用等值（\"谋生\"→making a living）；增补（their）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`spend time doing sth`（L2·SB）；`make a living`（L2·PC）。"}, {"term": "", "zh": "", "cn": "然而，近年来中国旅游业发展迅速。", "en": "However, in recent years China's tourism industry has developed rapidly.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;①\"然而\"→转折(However);时锚:近年来→现在完成时;文化:旅游业→S1 tourism industry（库；tourism）", "ta": "连接词前置（However，连淑能 1993）；补主语。", "te": "增补（rapidly）；词性转换。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"旅游/旅游业\"库内作 tourism，S1。", "rp": "`develop rapidly`（L2·PC）。"}, {"term": "", "zh": "", "cn": "经济的繁荣和富裕中产阶级的出现，引发了一个前所未有的旅游热潮。", "en": "Economic prosperity and the emergence of a wealthy middle class have triggered an unprecedented tourism boom.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:长主语\"…和…\"→名词化主语;文化:中产阶级→the middle class（S4 通译）；旅游热潮→a tourism boom（S4 通译）", "ta": "话题→主语（名词化主语，连淑能 1993）；补主语。", "te": "词性转换（\"繁荣\"→prosperity，\"出现\"→the emergence）；增补（wealthy）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`trigger a … boom`（L2·PC）；`the emergence of`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国人不仅在国内旅游，出国旅游也越来越普遍。", "en": "Chinese people not only travel within China, but also increasingly travel abroad.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;①\"不仅…也…\"→not only…but also…;文化:国内旅游→domestic travel（S4 通译）；出国旅游→travel abroad（S4；\"出境旅游\"库内 outbound tourism S1）", "ta": "意合→形合（not only… but also…，连淑能 1993）。", "te": "增补（increasingly）；惯用等值（\"在国内\"→within China）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"出境旅游\"库内作 outbound tourism（China Daily），S1，本句\"出国旅游\"作通译 travel abroad（S4）。", "rp": "`not only … but also …`（L2·SB）；`travel abroad`（L2·PC）。"}, {"term": "", "zh": "", "cn": "2016 年国庆节假日期间，旅游消费总计超过 4000 亿元。", "en": "During the 2016 National Day holiday, tourism spending totaled more than 400 billion yuan.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;时锚:2016年…期间→一般过去时;话题:补主语(→tourism spending);文化:国庆节→S1 the National Day holiday（定译）；旅游消费→tourism spending（S4 通译）", "ta": "时间状语前置；补主语（话题→主语，Li & Thompson 1976）。", "te": "增补（totaled）；数词处理（\"4000 亿\"→400 billion）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"国庆\"官方定名 the National Day（holiday），S1。", "rp": "`the National Day holiday`（L2·PC）；`total more than`（L2·PC）。"}, {"term": "", "zh": "", "cn": "据世界贸易组织估计，2020 年中国将成为世界上最大的旅游国，在未来几年里将成为出境旅游支出增长最快的国家。", "en": "According to the World Trade Organization, China will become the world's largest tourist country in 2020 and the country with the fastest-growing outbound tourism spending in the years to come.", "ptype": "真题", "cat": "真题B", "map": "度假与旅游", "set": "CET6 2016·12·S1", "src": "CET6 2016·12·S1", "cls": "Chapter 12", "tip": "断句:分句①\"据…估计\"/②\"2020年…旅游国\"/③\"在未来几年里…国家\";核心=②③;①→状语(According to…);时锚:将成为→一般将来时;文化:世界贸易组织→S1 the World Trade Organization (WTO)（专名定译）；出境旅游→S1 outbound tourism（库；China Daily）", "ta": "句首状语前置（According to…）；意合→形合（并列 and…，连淑能 1993）。", "te": "增补（in the years to come）；词性转换（\"增长最快\"→the fastest-growing）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"世界贸易组织\"专名定译 the World Trade Organization，S1；\"出境旅游\"见 China Daily（outbound tourism），S1。", "rp": "`the World Trade Organization`（L2·PC）；`the fastest-growing`（L2·PC）。"}, {"term": "", "zh": "", "cn": "北京计划未来三年投资 7 600 亿元治理污染，从减少 PM2.5 排放入手。", "en": "Beijing plans to invest 760 billion yuan over the next three years to control pollution, starting with reducing PM2.5 emissions.", "ptype": "真题", "cat": "真题B", "map": "北京治理污染", "set": "CET6 2014·06·S1", "src": "CET6 2014·06·S1", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=主句;①\"治理污染\"→目的状语(To control…)(CL-07);②\"从…入手\"→分词状语(starting with…);文化:治理污染→control pollution（库旁参 reduce pollution S4）", "ta": "目的状语化（连淑能 1993）；分词状语（starting with…）。", "te": "增补（over the next three years）；动词转动名词（\"排放\"→emissions，Vinay & Darbelnet 1958）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`start with`（L2·PC）；`invest … in doing sth`（L2·SB）。"}, {"term": "", "zh": "", "cn": "这一新公布的计划旨在减少四种主要污染源，包括 500 多万辆机动车的尾气(exhaust)排放、周边地区燃煤、来自北方的沙尘暴和本地的建筑灰尘。", "en": "The newly announced plan aims to reduce four major sources of pollution, including exhaust emissions from more than 5 million motor vehicles, coal burning in surrounding areas, sandstorms from the north and local construction dust.", "ptype": "真题", "cat": "真题B", "map": "北京治理污染", "set": "CET6 2014·06·S1", "src": "CET6 2014·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[旨在]→aim to do；[包括]→including…;文化:尾气→exhaust emissions（原卷括注 exhaust，同源优先）", "ta": "分词列举（including…，连淑能 1993）；补主语。", "te": "增补（major）；词性转换（\"燃煤\"→coal burning）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"尾气\"取原卷括注 exhaust（同源优先）。", "rp": "`aim to do sth`（L2·SB）；`sources of pollution`（L2·PC）。"}, {"term": "", "zh": "", "cn": "另 850 亿元用于新建或升级城市垃圾处理和污水（sewage)处理设施，加上 300 亿元投资未来三年的丝树造林（forestation)。", "en": "Another 85 billion yuan will be used to build or upgrade urban garbage and sewage treatment facilities, plus 30 billion yuan to be invested in afforestation over the next three years.", "ptype": "真题", "cat": "真题B", "map": "北京治理污染", "set": "CET6 2014·06·S1", "src": "CET6 2014·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;话题:受事\"资金\"→被动(will be used);文化:污水处理→sewage treatment（原卷括注 sewage，同源优先）；植树造林→afforestation；备注:[原卷如此]（\"丝树造林\"疑为\"植树造林\"之误，照抄不改；括注 forestation；\"污水（sewage)\"为全角左括号＋半角右括号，照抄）", "ta": "受事主语→被动（will be used，CL-04）。", "te": "增补（will be used, facilities）；词性转换（\"植树造林\"→afforestation）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"sewage\"取原卷括注（同源优先）。", "rp": "`A is used to V`（L2·SB）；`garbage and sewage treatment facilities`（L2·PC）。"}, {"term": "", "zh": "", "cn": "市政府还计划建造一批水循环利用工厂，并制止违章建筑，以改善环境。", "en": "The municipal government also plans to build a number of water recycling plants and stop illegal construction to improve the environment.", "ptype": "真题", "cat": "真题B", "map": "北京治理污染", "set": "CET6 2014·06·S1", "src": "CET6 2014·06·S1", "cls": "Chapter 12", "tip": "断句:单分句（连动）;核心=主句;①\"以改善环境\"→目的状语(to improve…)(CL-07);文化:水循环利用→water recycling；违章建筑→illegal construction", "ta": "补主语；目的状语后置（连淑能 1993）。", "te": "增补（a number of）；词性转换（\"水循环利用\"→water recycling）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`a number of`（L2·PC）；`water recycling plants`（L2·PC）。"}, {"term": "", "zh": "", "cn": "另外，北京还将更严厉地处罚违反限排规定的行为。", "en": "In addition, Beijing will punish violations of emission limits more severely.", "ptype": "真题", "cat": "真题B", "map": "北京治理污染", "set": "CET6 2014·06·S1", "src": "CET6 2014·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=①;触发[还将]→will（将来时）;文化:限排规定→emission limits", "ta": "补主语；衔接状语前置（连淑能 1993）。", "te": "增补（more severely）；名词化（\"违反…行为\"→violations of…）。", "srcEn": "S2 · 整句无官方译文（整理编译）。", "rp": "`in addition`（L2·PC）；`violations of …`（L2·PC）。"}, {"term": "", "zh": "", "cn": "随着中国经济的快速发展和人们生活水平的稳步提高，城市居民对环境和生活品质的要求越来越高。", "en": "With China's rapid economic development and the steady improvement of people's living standards, urban residents have increasingly high demands for the environment and quality of life.", "ptype": "真题", "cat": "真题B", "map": "城市公共设施与人居品质", "set": "CET6 2023·06·S1", "src": "CET6 2023·06·S1", "cls": "Chapter 12", "tip": "断句:分句①\"随着…提高\"/②\"城市居民…要求越来越高\";核心=②;①→背景状语(With…);时锚:越来越→一般现在时;文化:生活水平→S1 living standards（库）；生活品质→quality of life（库 S4）", "ta": "句首框架状语前置（连淑能 1993）；补主语（Li & Thompson 1976）。", "te": "增补（steady）；词性转换（\"提高\"→the improvement）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"生活水平\"见官方英文（living standards），S1；\"生活品质\"库内作 quality of life（S4）。", "rp": "`with the improvement of living standards`（L2·PC）；`quality of life`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国地方政府更加注重公共设施的建设和改进，以更好地满足人们的需求。", "en": "Local governments in China pay more attention to the construction and improvement of public facilities to better meet people's needs.", "ptype": "真题", "cat": "真题B", "map": "城市公共设施与人居品质", "set": "CET6 2023·06·S1", "src": "CET6 2023·06·S1", "cls": "Chapter 12", "tip": "断句:分句①/②\"以…满足…\";核心=①;②→目的状语(to better meet…)(CL-07);文化:地方政府→local governments（S4 通译）；公共设施→public facilities（S4 通译；邻条 fitness facilities S1）", "ta": "补主语；目的状语后置（连淑能 1993）。", "te": "增补（better）；词性转换（\"建设/改进\"→construction/improvement）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"公共设施\"库内无同形官方直配，按语境通译 public facilities（S4；邻条 fitness facilities S1）。", "rp": "`pay attention to`（L2·PC）；`meet people's needs`（L2·PC）。"}, {"term": "", "zh": "", "cn": "通过兴建新的广场、公园和公共绿地或对原有公共场地重新加以规划改造，许多城市为市民提供了更多休闲和社交的场所。", "en": "By building new squares, parks and public green spaces or re-planning and renovating existing public spaces, many cities have provided citizens with more places for leisure and social activities.", "ptype": "真题", "cat": "真题B", "map": "城市公共设施与人居品质", "set": "CET6 2023·06·S1", "src": "CET6 2023·06·S1", "cls": "Chapter 12", "tip": "断句:单分句;核心=主句;①\"通过…\"→方式状语(Through…);文化:公共绿地→S1 public green space（库；武汉市政府英文站）；休闲和社交的场所→places for leisure and social activities（库 S4）", "ta": "方式状语前置（By＋动名词，连淑能 1993）；补主语。", "te": "动词转动名词（\"兴建/规划改造\"→building / re-planning and renovating，Vinay & Darbelnet 1958）；增补（citizens）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"公共绿地\"见武汉市政府英文站（public green space），S1；\"休闲和社交的场所\"库内作 places for leisure and social activities（S4）。", "rp": "`By V-ing …, S + V …`（L2·SB）；`places for leisure and social activities`（L2·PC）。"}, {"term": "", "zh": "", "cn": "如今，政府出资购置的健身器械和铺设的健身步道在不少城市随处可见，既明显改善了市民户外活动的条件，又使城市更加美丽。", "en": "Today, government-funded fitness facilities and fitness trails can be seen everywhere in many cities, which has both clearly improved the conditions for citizens' outdoor activities and made the cities more beautiful.", "ptype": "真题", "cat": "真题B", "map": "城市公共设施与人居品质", "set": "CET6 2023·06·S1", "src": "CET6 2023·06·S1", "cls": "Chapter 12", "tip": "断句:分句①\"健身器械…步道…随处可见\"/②\"既…又…\";核心=①;②→非限定从句(which…)|并列状语;时锚:如今→一般现在时;触发[既…又…]→both…and…|not only…but also…;文化:健身器械→S1 fitness facilities（库）；健身步道→S1 fitness trails（库）；户外活动→S1 outdoor activities（库）；随处可见→can be seen everywhere（库 S4）", "ta": "补主语；意合→形合（非限定 which 从句，连淑能 1993）、并列结构（both…and…）。", "te": "增补（Today, government-funded）；词性转换（\"条件\"→conditions）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"健身器械/健身步道/户外活动\"分别见 China Daily / 深圳市政府英文站（fitness facilities / fitness trails / outdoor activities），S1；\"随处可见\"库内作 can be seen everywhere（S4）。", "rp": "`be seen everywhere`（L2·PC）；`both … and …`（L2·SB）。"}, {"term": "", "zh": "", "cn": "近年来，中国城市加快发展，城市人居环境得到显著改善。", "en": "In recent years, Chinese cities have developed at a faster pace, and the urban living environment has improved markedly.", "ptype": "真题", "cat": "真题B", "map": "城市人居环境", "set": "CET6 2023·06·S3", "src": "CET6 2023·06·S3", "cls": "Chapter 12", "tip": "断句:分句①/②;核心=①;②→并列(and… has improved markedly);时锚:近年来→现在完成时;话题:补主语(→Chinese cities / the urban living environment);文化:城市人居环境→urban living environment（库 living environment S1）", "ta": "补主语；时间状语前置（In recent years，连淑能 1993）；时态呼应（现在完成，连淑能 1993）；意合→形合（and，连淑能 1993）。", "te": "动词\"加快发展\"→develop at a faster pace；增补（markedly）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"（居住）环境\"库内作 living environment（CCTV 英文版），S1（urban living environment 为组合通译）。", "rp": "`in recent years`（L2·PC）；`at a faster pace`（L2·PC）。"}, {"term": "", "zh": "", "cn": "许多城市努力探索中国特色的城市高质量发展之路，城市功能不断完善，治理水平明显提高。", "en": "Many cities have worked hard to explore a path of high-quality urban development with Chinese characteristics, with urban functions continuously improved and governance significantly enhanced.", "ptype": "真题", "cat": "真题B", "map": "城市人居环境", "set": "CET6 2023·06·S3", "src": "CET6 2023·06·S3", "cls": "Chapter 12", "tip": "断句:分句①②③;核心=①;②③→伴随/并列(独立主格 with…);话题:补主语(→Many cities);时锚:完善/提高→现在完成时;文化:中国特色→S1 with Chinese characteristics（库）；高质量发展→S1 high-quality development（库定译）；城市功能→S1 urban functions（库）；治理水平（城市治理）→S1 urban governance（库）", "ta": "补主语；独立主格（with…，连淑能 1993）；时态呼应（现在完成，连淑能 1993）。", "te": "动词\"探索\"→explore；增补（continuously / significantly）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"中国特色\"（with Chinese characteristics）、\"高质量发展\"（high-quality development）、\"城市功能\"（urban functions）、\"治理水平/城市治理\"（urban governance）见官方行文 / 人民日报英文版，S1。", "rp": "`work hard to V`（L2·PC）；`a path of … development`（L2·PC）。"}, {"term": "", "zh": "", "cn": "中国持续开展城市生态修复和功能修补，全面实施城镇老旧小区改造，大力推进城市园林绿化，消除污染；同时大力推进城市基础设施体系化建设，开展房屋建筑和市政设施普查以及安全隐患排查整治，努力为市民创造高品质的生活环境，让城市更美丽、更安全、更宜居。", "en": "China has continuously carried out urban ecological restoration and urban repair, fully implemented the renovation of old residential communities in cities and towns and vigorously promoted urban greening to eliminate pollution; at the same time, it has vigorously advanced the systematic development of urban infrastructure, carried out surveys of buildings and municipal facilities as well as the screening and rectification of potential safety hazards, and worked hard to create a high-quality living environment for urban residents, making cities more beautiful, safer and more livable.", "ptype": "真题", "cat": "真题B", "map": "城市人居环境", "set": "CET6 2023·06·S3", "src": "CET6 2023·06·S3", "cls": "Chapter 12", "tip": "断句:分句①—⑥;核心=①;②③④→并列谓语;⑤⑥→并列(同时…);话题:补主语(→China);时锚:开展/实施→现在完成时;文化:城市生态修复→S1 urban ecological restoration（库）；功能修补→urban repair（库 S4）；城镇老旧小区改造→S1 renovation of old residential communities（库）；城市园林绿化→S1 urban greening（库）；城市基础设施→S1 urban infrastructure（库）；安全隐患→potential safety hazards（库 S4）；宜居→S1 livable（库）；更美丽、更安全、更宜居→S1 greener, safer cities（库；人民日报英文版）", "ta": "补主语；意合→形合（分号并列两分句，连淑能 1993）；时态呼应（现在完成，连淑能 1993）；分词状语（making cities…）。", "te": "动词\"开展/实施/推进/创造\"→carried out / implemented / advanced / create；增补（systematic / high-quality）。", "srcEn": "S2 · 整句无官方译文（整理编译）；\"城市生态修复\"（urban ecological restoration）、\"城镇老旧小区改造\"（renovation of old residential communities）、\"城市园林绿化\"（urban greening）、\"城市基础设施\"（urban infrastructure）、\"宜居\"（livable）见 CCTV 英文版 / 人民日报英文版，S1；\"功能修补\"（urban repair）、\"安全隐患\"（potential safety hazards）库内通译，S4。", "rp": "`carry out … restoration`（L2·PC）；`work hard to V`（L2·PC）；`make cities more …`（L2·PC）。"}], "exercises": [{"sec": "Comprehension 理解 · Fill in the Blanks 填空", "kind": "fill", "intro": "Fill in the following blanks with the information you learned from the reading text.", "qs": [{"no": 1, "q": "The launch of ______ and the promotion of cultural revitalisation in ______ have been enriching residents' lives and fostering a sense of community.", "ans": "public-interest cultural programmes；rural areas", "src": "课文 u2_s1_p5：The launch of public-interest cultural programmes (文化惠民工程) and the promotion of cultural revitalisation in rural areas bring more cultural performances and activities to rural communities, enriching residents' lives."}, {"no": 2, "q": "Digital entertainment has become an integral part of modern life, enabling people to chat online, ______, ______, and visit ______ museum exhibitions.", "ans": "watch livestreams；shop online；virtual", "src": "课文 u2_s3_p1：From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions and experiencing smart tourism (智慧旅游), digital entertainment has become an integral part of modern life."}, {"no": 3, "q": "Xi'an features the ruins of several grand imperial palaces and contains numerous historic monuments, such as the Great Mosque, ______, the Small Wild Goose Pagoda, and ______.", "ans": "the Big Wild Goose Pagoda；the Bell and Drum Towers", "src": "课文 u3_s6_p1：The city also contains numerous other historic monuments, including the Great Mosque (大清真寺), the Big Wild Goose Pagoda (大雁塔), the Small Wild Goose Pagoda (小雁塔), and the Bell and Drum Towers."}, {"no": 4, "q": "National archaeological site parks combine archaeological sites with ______ through scientific planning and meticulous ______.", "ans": "natural landscapes；protection", "src": "课文 u4_s4_p1：Combining archaeological sites with natural landscapes through scientific planning and meticulous protection, these sites are all precious legacies of ancient Chinese civilisation."}, {"no": 5, "q": "China's red tourism, with its roots in the country's revolutionary history, serves as an important avenue for ______ and plays a key role in preserving and transmitting the ______.", "ans": "patriotic education；revolutionary spirit", "src": "课文 u4_s5_p1：It serves as an important avenue for patriotic education and plays a key role in preserving and transmitting the revolutionary spirit."}]}, {"sec": "Comprehension 理解 · Answer Questions 简答问答", "kind": "fill", "intro": "Answer the following questions.", "qs": [{"no": 1, "q": "In what ways have cultural leisure activities in China become richer and more diverse?", "ans": "Cultural leisure activities in China have become richer and more diverse in recent years in several ways. First, the country has greatly expanded its cultural infrastructure, with thousands of museums nationwide using innovative technologies to create immersive experiences. Second, the performing arts sector has flourished, exemplified by venues such as the National Centre for the Performing Arts, which hosts a wide range of concerts, operas, and theatrical productions. Third, new cultural and creative spaces like Shanghai’s Tianzifang and Beijing’s 798 Art District have emerged, offering art exhibitions, workshops, and opportunities for creative exchange. Finally, cultural revitalisation in rural areas has brought traditional events, local performances, and public-interest cultural programmes to village communities, making cultural life more vibrant and inclusive across the nation.", "src": "课文 u2_s1_p2：China has witnessed a significant expansion of its cultural infrastructure."}, {"no": 2, "q": "What makes China's natural attractions so remarkable and appealing to visitors?", "ans": "China’s natural attractions are remarkable for their breathtaking beauty, ecological significance, and deep cultural heritage. Famous mountains such as Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer majestic scenery and reflect centuries of artistic and spiritual tradition. Scenic areas like the Jiuzhaigou Valley and the Zhangjiajie National Forest Park showcase stunning landscapes of lakes, waterfalls, and unique rock formations, while also highlighting local ethnic cultures. The Sanjiangyuan (Three-River-Source) National Park is both an ecological treasure and one of the birthplaces of Chinese civilisation. Together, these sites embody the harmony between nature and culture, providing visitors with unforgettable experiences of China’s natural splendour and its rich history.", "src": "课文 u3_s8_p1：As well as its significant cultural and historical attractions, China has a great many breathtaking natural attractions. Mount Huangshan, Mount Taishan, and the Tianshan Mountains offer spectacular mountain scenery, while the Jiuzhaigou Valley Scenic and Historic Interest Area, the Zhangjiajie National Forest Park, and the Sanjiangyuan (Three-River-Source) National Park boast some of the country's most stunning natural landscapes."}]}, {"sec": "Translation 翻译 · Term Translation 术语翻译", "kind": "fill", "intro": "", "qs": [{"no": 1, "q": "智慧旅游", "ans": "smart tourism", "src": "课文 u2_s3_p1：From chatting online, watching livestreams, and shopping online to visiting virtual museum exhibitions and experiencing smart tourism (智慧旅游), digital entertainment has become an integral part of modern life."}, {"no": 2, "q": "文化创意产业", "ans": "cultural and creative industry", "src": "课文 u2_s1_p4：For example, Shanghai's Tianzifang is an international cultural and creative industry zone that is home to nearly 400 stores, including art galleries, studios, handicraft stores, fashion boutiques, restaurants, and cafés."}, {"no": 3, "q": "长江三角洲", "ans": "Yangtze River Delta", "src": "课文 u3_s4_p1：Situated on the southern wing of the Yangtze River Delta, Hangzhou was the capital of the Wuyue Kingdom during the Five Dynasties and Ten Kingdoms period and later became the capital of the Southern Song Dynasty."}, {"no": 4, "q": "数字娱乐", "ans": "digital entertainment", "src": "课文 u2_s3_p1：digital entertainment has become an integral part of modern life."}, {"no": 5, "q": "爱国主义教育基地", "ans": "education base for patriotism", "src": "课文 u4_s5_p2：This scenic area is a representative example among the 445 revolutionary relics found in Yan'an. It has been designated as a major national education base for patriotism, revolutionary tradition, and the \"Yan'an spirit\"."}]}, {"sec": "Translation 翻译 · Passage Translation 段落翻译", "kind": "passage", "intro": "", "cn": "虚拟博物馆展览已经成为现代中国人文化生活中不可或缺的一部分，为公众提供了便捷的文化体验方式。通过在线展览、虚拟导览和互动式数字项目，虚拟博物馆打破了时间和空间的限制，让人们足不出户就能欣赏历史文物和艺术珍品。例如，故宫博物院推出的\"云游故宫\"项目，包括全景导览和数字文物展示，吸引了大量观众。虚拟博物馆还提供互动体验，如人工智能导览、智能问答等，增强观众的参与感。此外，虚拟博物馆通过数字化手段实现了文化遗产的永久保存与全球共享。", "ans": "Virtual museum exhibitions have become an indispensable part of the modern cultural life of the Chinese people, offering the public convenient access to cultural experiences. Through online exhibitions, virtual tours, and interactive digital programmes, virtual museums break the constraints of time and space, enabling people to appreciate historical relics and artistic treasures without leaving home. For example, the Palace Museum’s Cloud Tour Programme, including panoramic tours and digital displays of cultural relics, has attracted large audiences. Virtual museums also provide interactive experiences, such as AI-powered virtual guides and smart Q&A services to enhance visitor engagement. In addition, through digitisation, virtual museums enable the permanent preservation and global sharing of cultural heritage.", "src": ""}, {"sec": "Critical Thinking and Discussion 思辨与讨论", "kind": "open", "intro": "", "qs": [{"no": 1, "q": "Form groups of four to five. Each group selects one topic for an in-depth discussion on the relationship between tourism and cultural heritage in China. Choose one of the following topics.\n\n1 The role of tourism in preserving traditional Chinese history and cultural heritage\n2 How cities such as Hangzhou and Xi'an balance modernisation with the conservation of historical sites\n3 The role of red tourism in promoting China's revolutionary history and its relevance to modern society\n\nDuring the discussion, analyse the key ideas, share examples and insights, and be prepared to present your group's conclusions to the class.", "ans": "", "src": ""}]}, {"sec": "Communication 口语任务", "kind": "open", "intro": "", "qs": [{"no": 1, "q": "Imagine you are part of a tourism promotion team for your city. Your task is to design a promotional event for international tourists that highlights the unique blend of historical and natural attractions in China. Work in groups and create a proposal for the event that includes:\n\n1 a brief introduction to China's top tourist cities and attractions\n2 a detailed itinerary for a week-long tour that covers key cultural and natural sites\n\nYour proposal should outline the main highlights, activities, and experiences for each destination, emphasising how the event promotes China's rich heritage and scenic beauty.", "ans": "", "src": ""}]}], "vocabHF": []}